insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "a58dfd58-07d2-4881-a1c5-49cf11bff7b7", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 13, "content": "Kyle Pusateri (23:15): Sure. So first of all, our marketing department, they are so intelligent and savvy and work as that link between our product managers and the engineering teams and they do a fantastic job, but as it relates to production, so more to the core of your question, I love having a marketing manager on set. Honestly, it makes things really smooth and it's a quick gut check to be able to say, Hey, how are we feeling? Are we feeling like this is an accurate way, especially with some of the more complex or detail features that we may be highlighting. (23:54): I was raised under the five Ps, prior preparation prevents poor performance. So what I take that to heart in the sense of making sure that I'm a bulldog dude, I will work with the producer on the other side or the photographer or a combination of the two and want to ask, build a bulletproof schedule, tell me what that looks like pre-pro harder. I love that idea. Maybe it's crafting a really concise, yet informative email. I feel really good about writing good emails, Cole, I take some pride in that or building a really tight schedule or something that maybe a couple options. Maggie, our EP and I like to say hashtag CLO creatives love options. So be able to know that we can say, okay, here's maybe one way that we could approach it, but what's another way and then what's another way? And having that fly by conversation with the creatives at their desk to say like, all right, hey, I've been thinking about this a few different ways we could go this direction. (24:56): Maybe this person would be good for this project or we could go this way and we could do it with this person. And having a balanced open discussion about it instead of feeling like, okay, well we're going to go with the same person we did for the last one and we know that looked great and everybody was happy. It's like, yeah, it feels like we're selling ourselves a little short. Why not try to push the creative, push each other in a good way, in a healthy way instead of just feeling satisfied with where we are currently and being complacent or just and making compromises.", "token_estimate": 534, "speakers": ["Kyle Pusateri"], "start_timestamp": "23:15", "end_timestamp": "23:15", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "997dfe8e-1611-499d-8066-27ef87e739ff", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 14, "content": "Cole Heilborn (25:31): Yeah, no, that feeling of, I mean it can never be perfect, so at some point it has to be done, but how do you push beyond that complacency? Yeah, that's a great question and I feel like the question you always have to ask yourself as you're working on something, you talk about the different levels of projects that you're producing, so you've got big campaign projects and you've got smaller shoots that could be flat lays or just social content or whatever. What's the balance between big shoots and small shoots if you had to simplify it into those two buckets?\n\nKyle Pusateri (26:02): Honestly, it's being on your toes and taking any projects that may come across your desk and doing it with the same enthusiasm as you may approach something that you're really passionate about. I'm sure you're like this as well. You're a responsive person and really keep an eye on top of email and you've got many projects in the hopper at one time and seemingly you do a great job. I think of not only bouncing port side but then also back country marketing podcast. I think there's a lot of irons in the fire at one time. It's keeping composure, realizing that you've got a good support system at the company that will certainly jump in or be able to help you at any point if you get into a spot where it may get a little tight. But then also feeling like you want to keep everybody safe, like the creative team, making sure that they know that okay, there may be multiple, I may be producing several jobs with different creatives who may have no idea that I'm doing things on other, I want to make them feel like I'm their only producer and that I'm working on this just as in depth as they are and have that same passion and care to execute and to produce it really the best way that we can together.", "token_estimate": 455, "speakers": ["Cole Heilborn", "Kyle Pusateri"], "start_timestamp": "25:31", "end_timestamp": "26:02", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "cda37c5e-2369-4624-9ad2-80af9040820d", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 15, "content": "Cole Heilborn (27:30): Let's pivot a little bit. So one, I feel like I've learned a lot just listening to you kind of share what is it like to be inside Garmin producing work that's really fascinating and I feel like it's fascinating on many levels because maybe I think that's what's so interesting is everyone comes to production in a different place. Just yesterday I was talking with the brands in the ski and snow sports world and they're like, yeah, we have the two freelancers that we hire every year to go out and do some shoots and that's all we can pull off. And they figure out how to make it work. And I feel like maybe the common denominator, whether you're working at Garmin where there's hundreds of shoots happening or you're working in a small brand, a startup brand that's just kind of piecing together shoots as you can. It's all kind of that DIY, we'll figure it out spirit that seems to drive a lot of people in the production world. Do you agree?\n\nKyle Pusateri (28:31): Of course. I mean we have to be resourceful and realize that there are and surround yourselves with good people who also care and want to see the project succeed. Fortunately here at Garmin, like I've been saying, everybody's all in all the time and you feel that and it's infectious, it's refreshing because then you feel good about giving it your all each day, but getting creative about solutions, and that's one thing I made a note of this, can we eradicate problem solving? Can we spin it into a positive and do like solution finding or something Problem solvers, I agree that that is who we are and I think at the core we do that. But\n\nCole Heilborn (29:20): Don't you like about that?\n\nKyle Pusateri (29:21): Well, problem just sounds so it's got a negative connotation to me immediately out the gate and it's like, well, yes, we are professional problem solvers, sure, but we also are being proactive about solutions. I think that we're anticipating the problems before they become one.\n\nCole Heilborn (29:36): What about route finders?", "token_estimate": 510, "speakers": ["Cole Heilborn", "Kyle Pusateri"], "start_timestamp": "27:30", "end_timestamp": "29:36", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "b351170e-d4b0-4dc2-9baa-8426535603c7", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 16, "content": "Kyle Pusateri (29:37): That's even more applicable I think especially for us it on just where you're from because our UK team would say, is it route or route? But absolutely, I think that route finding to me feels more forward looking and proactive in the sense that you are okay, you may not anticipate or you may not experience any issues or a problem, but because you've thought about it or anticipated any potential pitfalls, you feel prepared to address them in the moment. And I'm not naive to think that there are problems we will encounter that we haven't prepared for. And so I'm not saying that we can prepare for everything, but having the idea that, okay, it's not going to be perfect, but how do we know maybe where are there some points throughout the production process and while you're putting together the schedule that could say, okay, look, that feels tight. (30:33): Maybe we should allow ourselves a little bit more time or making adjustments on the fly, feeling confident with the team and in a good flow state that you can actually say, okay, team, we're getting what we need. Maybe we're a little bit behind, but we know we're going to make it up. Those constant conversations, the check-ins, Cole, I know you know this, but can we step away and have a sidebar for five minutes? I mean the value of those onset, whether it's with the director or the photographer or if it's just the Garmin team, having those opportunities to break away and just ensure alignment is so important and valuable throughout the day just to make sure that you all are on the same page and doing it in a calm and respectful manner because we all know that they're the talent, the crew, they're looking at us, right? We need to be the captain of the ship and to be able to say, look, we've got this together. Inevitably will be things that we'll encounter that we weren't prepared to address. But you know what? We're smart and we're prepared. We are at this point. Let's figure this out and pivot and move on.", "token_estimate": 503, "speakers": ["Kyle Pusateri"], "start_timestamp": "29:37", "end_timestamp": "29:37", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "31a2a6fa-e3f3-4268-97fb-24e867c0199c", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 17, "content": "Cole Heilborn (31:44): Yeah, I think I learned that lesson. There's one shoot that I did that or I learned that lesson the hard way. We were on location in another state shooting, the light was disappearing. We were shooting some product and I was stressed. I was directing and I was like, are lights disappearing? It took us longer to get to the location than we thought it would.\n\nKyle Pusateri (32:07): So what you experienced in the way you felt Cole is universal. We've all been there at one point where we can feel we're stressed. There's a lot going on. So many things racing through our brains. We've got people looking at us wondering what we need to do next. So that feeling I've been there. I think we all have. And so it's something that I've learned also to make sure that you maintain that composure and to really keep that poker face because the last thing you want to do is throw the creatives off their mission.\n\nCole Heilborn (32:42): I mean, your job is unique in that you're reviewing locations, you're reviewing people and characters that you're working with. As you mentioned earlier, even use the example of a bike, which bike best is the best platform to put our unit on for this shoot? Those are all the really small details that people don't think about when they watch something, but they're things that we think about in production because we know, oh, if we cast this person, then this person will represent or speak to this group of the population or this demographic of our audience. Or if we use this bike subconsciously, this bike means this to this group of cyclists. Tell me more about how much time do you spend thinking about those nitty gritty details and giving yourselves options to consider like, oh, what if we use this bike versus this bike or this trail shoe versus this trail shoe?", "token_estimate": 457, "speakers": ["Cole Heilborn", "Kyle Pusateri"], "start_timestamp": "31:44", "end_timestamp": "32:42", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "f28d7769-b642-4702-b327-5916d9977aca", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 18, "content": "Kyle Pusateri (33:34): Totally. And I do spend a lot of time thinking about those details because they're important. Those are the things that people who know will be looking for. So if we've got a TT bike on a gravel scene, people are going to know that we don't know what we're talking about. So you lose credibility right out of the gate. So those details matter. And I guess the way that I think what you're asking is then what I'm looking for maybe when seeing those, so I know BTS is something that we were talking about in our emails leading up to this, and you've posted a few times even on LinkedIn, but CN and read your blog post about it, also storyboarding and the fake rain example. I just thought those are the types of examples that I'd much rather see. Yes, send me a link to your site and show the final version of whatever it may be, the video or the final image, but tell me how you got there, articulate the route that you took to achieve that shot. (34:39): Tell me about the problems, the hiccups that you encountered along the way that is in totality what we will see and help us evaluate if you are the right type of production partner for Garmin, because we're small, nimble in-house teams. I'm bringing an art director, a writer and myself on some of these off the grid types of shoots where we need a production partner that's going to get gritty and be brave and help guide us out into the wilderness to make some really great content. And I want to know, and I know the team does too, about the coolest rig you just built or what kind of lenses you're planning to execute this type of shot to get the effect we're seeking. Or you've got some talent who isn't through an agency, but you met them at your local run club and think that they would be incredible because of what as a shooter. (35:38): Those are the types of things that I think, or an epic location. It's something that, or the example we gave about foliage in your area. And so finding those are the intangibles that help give us a broader perspective on how you would approach production. It's not simply like, yes, we can execute the creative exactly the way you have it boarded and we'll say yes to everything you put in front of us or every question you ask, it's got to be collaborative, but show me how you made that cool stuff. Because I think we like seeing that because the way that it's made is something that gives us greater confidence in that we're finding the right partner because they know how to do whatever it takes to get the shot.", "token_estimate": 636, "speakers": ["Kyle Pusateri"], "start_timestamp": "33:34", "end_timestamp": "33:34", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "0ca49393-3679-48f8-b88f-18f3be2b8245", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 19, "content": "Cole Heilborn (36:25): Okay, this is interesting because okay, if you had to speak to creatives who are listening, and I hear this from you, and I'm like, okay, that's fascinating. Kyle is looking for, if I'm looking to work with Kyle, Kyle's looking to see how the sausage is made. He wants to see the rigs, he wants to see the lens choices, he wants to see all of the details that go into executing on a shoot. Some clients though, who are in a very different spot than you, they don't care about any of that stuff. And so I'm curious if you could speak to maybe the differences between what you look for versus what maybe a smaller team would look for in someone to work with because those are two very different, very two very different approaches, if that makes sense.", "token_estimate": 194, "speakers": ["Cole Heilborn"], "start_timestamp": "36:25", "end_timestamp": "36:25", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "a2e551e2-2e33-47ed-a0f1-5160fb217645", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 20, "content": "Kyle Pusateri (37:12): Of course. And certainly I think the size of the team, the resources that a company or a brand or an agency creatives may have at the ready varies. So for us, it's important to make sure that we can have a thorough understanding of your process and your team and your perspective. It's not just solely about how you're able to make pretty pictures or roll video in an epic location. It's seeing that you're giving the project additional thought beyond the ask. And I think that is at the core of what I'm saying when I mean that, I don't think in all cases we want to know all the lenses that you're using or our creatives are so multi-talented. I've got writers who shoot, I've got art directors who can edit. I've got editors who can write. And so I know that the reason I ask these questions upfront is so I know that those will be the types of questions the creatives will ask me. (38:26): So to be able to feel armed that, yeah, I had a great conversation with Cole. Here's a perfect case study of a project that he did recently, and look at this BTS blog post he did, and he goes into detail about how they made fake rain and did you know, you know that our concept calls for a rainy scene, and so he's got the credibility because he's done it before and worked with a great team to make it happen instead of just throwing money at a solution. I think that in some instances feels like the easy answer is, okay, well we need fake rain, so we got to call in a specialist and we got to fly somebody in and we got to get all this expensive equipment and blah, blah, blah. That to me isn't a solve not, I don't want you to come to me and say just because our ask may be shifted or we have something that when you bid the project you weren't accounting for, it's instead of saying, well, that's an overage. (39:23): Okay, no, let's back up a little bit and talk about how maybe we can find a solution together without compromising the creative and also not being unfair to the production partner on the project. It's a compromise and working together and being collaborative. But I would say for smaller teams, I think it's doing your due diligence and asking the production partner to be substantive in their examples that they're providing, to give you some examples of things that they've done that are similar or in a like-minded vein of what the project and is about. And so that way it gives you that greater confidence as you're going through pre-production to say, okay, they've encountered something similar. Or maybe it's not apples to apples. It could be a different production problem that you've solved, but at least it shows that you have the fortitude and the bravery to recover and to make really great work.", "token_estimate": 687, "speakers": ["Kyle Pusateri"], "start_timestamp": "37:12", "end_timestamp": "37:12", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "8dcbcd98-a6b8-45ad-9ca3-b45d192a3317", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 21, "content": "Cole Heilborn (40:31): Okay, can we zoom out a little bit? Sure. We've been in the weeds. We're both wearing hats. Let's take off our hats and put on our CMO hats. We could just, I want to kind of pick your brain on the world of media from the 30,000 foot level and I guess as it pertains to the outdoor and the fitness world, where do you feel like this world of media is going? Do you feel like it has a direction that you're seeing and you're sensing? What do you think?\n\nKyle Pusateri (40:58): So I want to harken back to your conversation with Mark Bach from Gore-Tex feel like he, and you mentioned this in your latest fireside chat, also think he does a good job of articulating the corporate needs, the audience needs, and then the media strategy and how those three concentric circles overlap to focus on storytelling and that sort of being that sweet spot. There are a few other factors that I think contribute to help make storytelling feel as strong as it can be and an important vehicle for brands to establish equity with their audiences and with their customers. I think where it's going and what we need to be doing is that first six seconds thinking about short form, and we all love to talk about long form and long form is amazing, and in terms of where we're going and what we're seeing is that first six seconds is just imperative. (41:56): And when I say that, I mean most notably for social. And I think another thing Mark mentioned on his chat with you as the atomization of content and how it's not only focusing on how this is going to live on social, but then what is the landing page going to look like? What are banners that are corresponding with it? What are the p os displays? It's really having that 360 view of the idea. But I think that as we put a focus on video, and its tough to keep up with algorithms and the way that social is evolving, but capturing that customer, that viewer within the first six seconds seems imperative for you to have them stay engaged. And so really thinking about, I think the creative teams do a phenomenal job of focusing on what's the hook, what's a way to keep them engaged and excited and then to continue watching because just the attention spans, as we all know, are just decreasing as time goes on. So as we continue to get, just to get flooded with marketing messages each and every day, so how do we hook them? And then for a longer term play, how do we keep the corporate objectives, the corporate needs, the audience needs those insights and also media strategy. How do we keep all of those in mind and then find that sweet spot for content?", "token_estimate": 655, "speakers": ["Cole Heilborn", "Kyle Pusateri"], "start_timestamp": "40:31", "end_timestamp": "40:58", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "a4022c16-8d87-46f7-a81d-b3de80d9a4bf", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 22, "content": "Cole Heilborn (43:31): I love that you bring up the first six seconds. So this is a working theory that I have, and I want to hear your thoughts. I feel like the first six seconds are the hook, otherwise essentially the question that that every person has when they watch something is why should I care? And the hook, I feel like ideally should answer that question. And if you can answer that question, then people are in it, right? They're like, they're interested in what you have to show, but if you can't answer that question, why should I care? Or why does this matter? I mean, I find myself clicking out of stuff or moving on because why should I care? There's going to be another brand that's going to throw something in my face in the next five minutes. So\n\nKyle Pusateri (44:14): You're right. And that I think is being an honest customer, someone who you're really thinking about it probably more deeply than the average person because they're just swiping, scrolling onto the next, that is something to consider as you are pitching ideas. Why would this fit so uniquely for that brand? I guess if you're savvy enough, I think of a marketer and I'd like to give your audience that credibility and that credit, because they're invested, they care about the topics you're covering, the people you're interviewing, and so thinking back, just not presenting or pitching an idea that feels like you're shopping it around, that you've just taken something off the shelf and you're saying, oh, well we'll try with Garmin or we'll try with another brand. And just because it feels like it may be something that they'll buy into, I mean, that's like fishing without bait to me. You're not really making it feel like it's something that would be unique for us and totally ownable together, I guess.", "token_estimate": 450, "speakers": ["Cole Heilborn", "Kyle Pusateri"], "start_timestamp": "43:31", "end_timestamp": "44:14", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "8ec51458-f15c-4418-b23a-af060788a761", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 23, "content": "Cole Heilborn (45:23): I love that. That's even a great, even if you're working internally developing concepts or trying to find stories to tell internally, that's a great question to ask. How does this story or this idea, what's unique about it? Why is it Garmin and why is it not any other tech brand? What's unique about this that's truly us? I like that. That's a good question. I'm going to write that down and use that.\n\nKyle Pusateri (45:49): Absolutely, and maybe test it out for a couple different brands and ideas. You may have to say, okay, why would Patagonia work or why would Arc Alteryx be a good brand? Or really thinking more deeply about your idea and strategically because ultimately that person that you're sending it to likely isn't the end recipient. That's one thing that I like to remind them is we have many stakeholders who are invested in this aspect of the business, this business segment. Let's make sure that the idea is fully baked, and that is something that we can confidently say is ownable for Garmin or for that brand, because otherwise it's just, it's a tough sell\n\nCole Heilborn (46:33): And\n\nKyle Pusateri (46:33): It makes it really hard for me to walk into a meeting and try to get the attention of a stakeholder who has five minutes. I mean, think of it like you've got six floors in an elevator ride with the CMO, what do you say? Or what's the pitch? And I know that sounds cliche, the elevator pitch, but at the same time, often that's the amount of time I have with decision makers here.\n\nCole Heilborn (46:59): And\n\nKyle Pusateri (47:00): So I love great treatments, don't get me wrong. And the opportunity to really articulate an idea, please don't stop sending them because they work. It's just work with me to refine it, to make it something that we can quickly digest and say, okay, yeah, tell me more.", "token_estimate": 464, "speakers": ["Cole Heilborn", "Kyle Pusateri"], "start_timestamp": "45:23", "end_timestamp": "47:00", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "b5601698-1396-4091-a47c-cc2ad1abd4b9", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 24, "content": "Cole Heilborn (47:19): This idea of asking why Garmin or why fill in the blank brand when it comes to producing content. If you're going to put your stamp of and put this out into the world, it needs to look, feel and breed Garmin, and ideally whatever is Garmin is different than every other brand out there. It's very you. So I see this, and I think we've talked about this on the show, is a lot of the content and stories that get produced in the outdoor industry look and feel very similar amongst each other. And there are similar stories. Maybe you swap out the logo at the beginning or the end of the spot and you're like, oh, is that this brand or this brand? It's hard to tell. Some brands do. I am generalizing some brands do this really well. It feels very them, but this homogenization of stories, I wonder if could be solved if we all asked ourselves more of the question of why is this story or this concept truly us? What makes a concept truly us versus someone else?\n\nKyle Pusateri (48:20): Absolutely. And that makes it so much more marketable and proves you've done your homework, you've thought deeply about it, you've thought strategically, and you're coming into the pitch feeling like you're doing more than just delivering creative. You're delivering something that could be a way for the brand to think differently about the way they approach business. I mean, who knows? The sky is really the limit in that sense because you're saying that you've given it some deep thought and that you truly believe that this approach or execution or whatever it may be, is the right fit for the brand. I guess I give a lot more credit and respect to those people who take the time and feel intentional about their ideas instead of just saying, oh, well, I've found their email and I'll shoot it over and see what comes back. I mean, that's so obvious with a shotgun approach when you just feel like you're one of 50 different producers that are probably getting the same pitch deck.", "token_estimate": 499, "speakers": ["Cole Heilborn", "Kyle Pusateri"], "start_timestamp": "47:19", "end_timestamp": "48:20", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "2f8d1ad1-f8cc-432d-8057-fdfa8e0495a9", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 25, "content": "Cole Heilborn (49:27): As we wrap up, I want to look towards the future and I want to understand what are you seeing, I guess, when it comes to two pieces of technology? I have to ask about ai. What do you think about AI and production? Do you feel like it's going to steamroll everyone who uses a camera? And my second follow up question to that is what about, are you familiar with the stagecraft technology, the video walls that Hollywood is using to film stuff on? Do you feel like where does that fit into this? Is that going to take over some of these shoots that are happening in the outdoor or fitness, I guess any of your categories that you're with?\n\nKyle Pusateri (50:06): Yes, in the future is inevitable and they're coming to take our jobs, the robots. I think at the end of the day, we're ultimately going to always want authenticity in all of our materials. So per Garmin, it's important to show people doing the activities they love in epic environments. I feel like that will be difficult to manufacture artificially in the future because at the crux, that's ultimately where we feel like our products are best represented. I won't speak too much creatively in terms of those concepts, but practically from a production standpoint, and given the fact that our company and our technology is rooted in GPS actually doing that authentically and going off the grid and taking real athletes who have proper form and to look the right part, but also are passionate about whatever activity it is that they may do that we're depicting, it's going to just be hard to replicate. I don't see artificial intelligence giving that personal touch to another individual on the other end to be able to make them feel like their credible or going to be taken care of, and that the idea will be executed in the best way possible. I'm not there with my confidence in what AI is able to do quite yet, but curious to hear your perspective.", "token_estimate": 484, "speakers": ["Cole Heilborn", "Kyle Pusateri"], "start_timestamp": "49:27", "end_timestamp": "50:06", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "a733ce17-848f-40ed-9678-70bd0d012e5b", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 26, "content": "Cole Heilborn (51:43): Yeah, I mean, I'm with you when it comes to on location stuff, that stuff has to be real. It has to be raw. For the 1% of people who watch a spot and they're like, oh, I've been there before that, as you were talking about earlier, that creates authenticity. (51:59): And I don't know how you fake that. I also think, yeah, when it comes to storytelling, people stories like docu projects, you can't fake that. That has to be real and rooted in reality for it to be credible. And so I don't think that's going anywhere. It seems like the type of work that could be hit the most is, and I don't know that this is even really super relevant for the outdoor community, is like the work that's all fiction. It's the type of work that isn't rooted in a real place or a real person. Everything is fabricated and it's shot on a studio. That's the type of stuff that feels like it could be on the chopping block in the future where, oh, maybe I just enter some prompts and I can create my own world with crazy visual effects. And that seems like it's going to have a much, I dunno, maybe the day of reckoning is coming for that type of work, the outdoor community. I don't know some of that gets produced, but I feel like the outdoor community is pretty safe. I did an interview actually a\n\nCole Heilborn (53:10): Few months ago", "token_estimate": 336, "speakers": ["Cole Heilborn"], "start_timestamp": "51:43", "end_timestamp": "53:10", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "266cc1ee-5863-4c26-a389-9a8b8cd150e0", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 27, "content": "Cole Heilborn (53:11): With Liz Eshi. She used to be in the outdoor industry. She's now at an AI company, and she had a really interesting prediction for brands, which I think impacts storytelling and media work. She was saying that in her perspective, what AI is going to do is essentially it's going to cut all of the BS out between brands and consumers. And so all it's going to be like if I wanted to find a watch, I could go, her theory is that we won't go to a search engine anymore. We'll just go to our own personal AI and I'll type in, I need to find a GPS watch that can do all these things to meet these needs that I have. And so then this AI goes out and scours the internet and pulls up all the options for me, and then I can look at all the options. (53:56): And she's like, if her conclusion was, if this AI is finding the product, evaluating it based on your activities, and then presenting three options other than price and design, what is your choice going to be based off of? And that last thing is it's brand. It's like that emotional connection that you build with that brand. And I've thought about that. Maybe that was almost a year ago that we had that interview, but I've thought about that ever since. That might be five years in the future, but it makes me think about the decisions that are made today to build that brand and how do we do that as filmmakers and as producers,\n\nKyle Pusateri (54:35): Our craft isn't going anywhere. I think there is an opportunity for us to continue to make great work that appeals to people's emotions and to their activities and their lifestyle throughout the course of time.", "token_estimate": 410, "speakers": ["Cole Heilborn", "Kyle Pusateri"], "start_timestamp": "53:11", "end_timestamp": "54:35", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "038fea6e-e434-4e26-93dc-da53f1ebc13b", "episode_id": "d0805a67-6899-495c-a040-0177710acf9b", "cms_item_id": "68225dfc7bb476527f8c495a", "chunk_index": 28, "content": "Cole Heilborn (54:50): Yeah, absolutely. Kyle, want to thank you for taking the time to sit down and chat. I mean it, it's been super fascinating just kind of hearing you talk about your work and the work that your team does, and I got to give you a round of applause and I guess your whole team for the amount of work that you guys really do behind the scenes to produce the work that we all see on the other end. It's impressive, and I think maybe that's what I'm excited to. One of the reasons I'm excited to get this episode out into the world is to show all the work that goes into production. I mean, we work with creative teams, we work with the marketing teams, but in some way, production is its own beast and there can be so much to it. And I think you've really shed a really nice light onto what it means to be a creative in the production world, in the outdoor industry. So thank you.\n\nKyle Pusateri (55:38): Well, thank you, Cole. And this has been an honor, and I'm very grateful for the opportunity, and I really hope we have an opportunity to work together someday and get a chance to explore the world and make some of the best work of our lives, because that's what it's all about.\n\nCole Heilborn (55:50): Yeah, absolutely. Well, Kyle, with that, have a great rest of your day. Keep us posted on where you're shooting next, and hopefully you get some sleep between now and then.\n\nKyle Pusateri (56:00): Yep. I'll check my sleep\n\nCole Heilborn (56:01): Score.\n\nKyle Pusateri (56:01): Thank you very much.\n\nCole Heilborn (56:02): All right, see you. Have a\n\nKyle Pusateri (56:03): Good one.\n\nCole Heilborn (56:04): Thank you for listening to this episode of the Backcountry Marketing Podcast. Please share it with a friend or leave us a review on Apple. ‍", "token_estimate": 443, "speakers": ["Cole Heilborn", "Kyle Pusateri"], "start_timestamp": "54:50", "end_timestamp": "56:04", "podcast_index": 191, "episode_name": "EP: 191 Inside the Creative Process with Garmin’s Lead Producer", "slug": "ep-191-inside-the-creative-process-with-garmins-lead-producer", "web_url": "https://www.portsidepro.com/podcast-feed/ep-191-inside-the-creative-process-with-garmins-lead-producer", "guest_name": "Kyle Pusateri", "guest_title": "Lead Producer at Garmin", "categories": ["creative", "brand"], "short_description": "Inside Garmin's creative team Kyle shares insights from his journey through account management to becoming a producer, providing a unique glimpse into Garmin’s creative ecosystem.", "podcast_length": "56:17"}, {"id": "668b6b15-7c43-44b9-b0a3-06df39e21b60", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 0, "content": "Chris Burkard (00:00): There used to be a very linear path to finding success and knowing that you nailed it. Now, there are so many channels and there's so many metrics. It's actually very convoluted and a little bit more complex, and I find that more often than not, people don't really know what they're looking for and people in the positions of creativity or marketing roles, it's more these days than just producing pretty images or a powerful video piece. Did it have the ROI did it, do this, did it do that? And it all starts to feel kind of homogenized. Just because something is getting views or likes or impressions does actually equate to sales, does it equate to value?\n\nCole Heilborn (00:40): Welcome to the Backcountry Marketing podcast. Today's guest needs little introduction. If you've spent any time in this industry, chances are you have come across Chris Burkard's work. He's a renowned photographer, adventurer athlete. When the opportunity came around to interview Chris for the show, it was an easy yes. This is part one of a two part episode we're doing with Chris. And the reason we want to do two parts is because we want to open it up to community questions. This first part was a really fun conversation and we talked specifically about creativity in the future of creative in this world of outdoor marketing. But the second episode, we want it to be driven by you guys. So if you have any questions for Chris, please submit them. Comment on the posts on social media. You can send emails to me, cole@portsidepro.com, and we'll do our best to answer 'em in a part two. Chris has been super willing to share his time and his expertise with us, and so I would love to source some amazing, really thought provoking questions from our community and be able to to chat about them on part two. Without further ado, enjoy this first episode, get a notepad and a pen ready, and write down any questions you might have. Welcome to the Backcountry Marketing podcast. Today I'm sitting down with Chris Burkardand , the photographer, creative director, adventurer amidst only many other titles. Chris, welcome to the show.", "token_estimate": 535, "speakers": ["Chris Burkard", "Cole Heilborn"], "start_timestamp": "00:00", "end_timestamp": "00:40", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "30a9e5be-349e-4a23-981f-09a87bcdeba8", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 1, "content": "Chris Burkard (02:03): Thanks for having me, man. I'm stoked to be here, especially after kind of fall in love with the podcast and sort of binging a few amazing episodes. I feel honored to be a part of it.\n\nCole Heilborn (02:14): I appreciate that this show wouldn't be anything without the folks that share their time and their insights. And so right back at you, you're helping bring together another episode we connected a couple of weeks ago, and we're trying to align on what could we talk about that might be a unique perspective. And if I had to sum up 2024, at least in my own perspective in one word, I might choose the word change because I feel like everything is changing. The role of creatives is changing in the outdoor industry, the needs that brands have this constantly changing. Channels are changing, audiences are changing. And amongst all that change is a lot of anxiety, but also opportunity. And I would love to hear your perspective on this topic of change.\n\nCole Heilborn (02:59): You could speak to that incredibly well. So I guess my first question is, do you see change happening all around you right now?", "token_estimate": 284, "speakers": ["Chris Burkard", "Cole Heilborn"], "start_timestamp": "02:03", "end_timestamp": "02:59", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "329ec07b-c726-417e-8924-2c7bfa3f2093", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 2, "content": "Chris Burkard (03:07): All around me all the time. And it's been an interesting path because not to date myself, but I've been doing this for a minute, and there are moments where I realize just how long I've been in the industry. And it's odd because there was for so many years, I was like, oh yeah, I'm the young gun. I'm the guy looking up at older people who were the creative directors or the art directors or whatever, the people that I was working with, the editors. And now I'm sort of looking down and I'm like, whoa, I'm older, or I'm at that age. And I think that what's most interesting to me, Cole, is there used to be a very linear path to finding success and knowing that you nailed it, knowing that you did the job that the brand or the magazine or whatever the title is that hired you wanted you to do. (03:59): And now, especially since social media, probably more so because now there are so many channels and there's so many metrics, it feels like the path is much less linear, it's much less straightforward. It's actually very convoluted and a little bit more complex. And I find that more often than not all due respect to people who hold these roles, but people don't really know what they're looking for and people in the positions of creativity or marketing roles, it becomes more challenging than ever as somebody who's the hired help, I guess you could say, to define really if you hit the mark, if you did a good job, it's more these days than just producing pretty images or a powerful video piece. Did it have the ROI did it, do this, did it do that? And to echo the words that some of the other really talented folks who you've interviewed have said, it all starts to feel kind of homo, homogenized, homogenous, I guess you could say. And it becomes a little bit complicated because just because something is getting views or likes or impressions does actually equate to sales. Does it equate to value? I don't know. And so yeah, to answer your question in a long-winded way, I agree there is a lot of change and it kind of keeps changing.", "token_estimate": 518, "speakers": ["Chris Burkard"], "start_timestamp": "03:07", "end_timestamp": "03:07", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "3e326898-9a66-4aaa-8e6f-5f9cff1f7353", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 3, "content": "Cole Heilborn (05:34): So you said times were simpler back in the day, so to speak, what you shot for a magazine, you got a cover, and that led to another cover and that led to more brand deals.\n\nChris Burkard (05:44): And I think more when you would oftentimes maybe 15, 16 years ago going out and shooting a commercial project, it was like, here's the brief. The brief is very clear, very simple, and I feel like I was working a lot of times with people who really knew what they wanted and could kind of set up some really safe guardrails for you, for us to play in. If you're the creative, the goal is to push the limits but not push it too far. And now I feel like it's a little different. You're being put into a role more so if you are a hired photographer, videographer, production, studio, whatever you're operating sometimes as a miniature creative agency a little bit. And that can be really fun. And trust me, I don't want to take anything away from that, but for those people coming up, it becomes a little bit complicated because you're having to do quite a bit and maybe some of that stuff is a bit out of your scope. And I think that brands are really leaning into creatives in that way quite a bit.\n\nCole Heilborn (06:53): So you mentioned, or you're alluding to the fact that maybe folks who work at brands maybe don't have as clear of directions as maybe they once did. And I'm curious if you could kind of explain that. What do you see and perhaps why is that?", "token_estimate": 370, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "05:34", "end_timestamp": "06:53", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "a274d87c-59d4-447f-938f-86fc5d56719a", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 4, "content": "Chris Burkard (07:05): Yeah, so I think I always sort of feel the conversation the same way, whether it's, I guess you could say I sort of operate in a few different worlds. I operate a bit in the photography production space with my studio. I also operate sort of in the influencer space a little bit. I also operate as an athlete in some capacity. So I often fill these different needs for brands and have sort of spread my tentacles out throughout. But I would say I start every conversation the same way. It doesn't really matter if I'm being hired to go shoot up Corona broadcast spot as a director or being asked to ride a bike as an athlete, how do we define success in this relationship? What would that look like at the end of the road? When all is said and done and the checks are sent and everything, what's going to make you feel good about this partnership? (07:57): And that is usually where I kind of get a long pause and I would say one time out of 10 I get an answer. Usually it's a bit more of like, okay, let's follow up. I'll let you chew on that. And that's really tricky because I feel like for me, it's more clear what I want, but I'm not the person who's paying the bills. And so I find that gives me a lot of pause that gives me a lot of maybe concern sometimes because if your people are in the position where they're spending the money, hiring the talent, hiring the whatever, and they don't really know what at the end of the day will successful look like. I mean, of course we can't always control these things, but I think that that gives me a little bit more concern as were before it was more linear. (08:49): Now, I want to just caveat that by saying that it's tricky because say you are in a production situation where you're the hired production company and you are making assets that then the brand can use on somebody else's channel. Does that make sense? If I'm being hired, CRISPR Studio or your production company is being hired to kind of make a video that then somebody on their team can promote on their social channels, or maybe there's a group of influential people who are going to spread that out. See, what's tricky is that you're not creating something for the brand's channels, you're creating something for somebody else's channels. And then whose fault is it? If it doesn't perform well, is it the brands? Is it yours? Is it theirs? Do you know what I'm saying?", "token_estimate": 604, "speakers": ["Chris Burkard"], "start_timestamp": "07:05", "end_timestamp": "07:05", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "27e16a42-888a-4347-82f3-ad0ee503f446", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 5, "content": "Cole Heilborn (09:39): Absolutely.\n\nChris Burkard (09:40): I mean exactly, because you've been there and I've been there too. And what ends up happening is at the end of the day, there's this happening. There's the point, the finger, and I totally forget her name. I think she was with Cotopaxi. She\n\nCole Heilborn (09:53): Kristen,\n\nChris Burkard (09:53): Yeah, she had just some great, I like great, I took a bunch of notes and she had some thoughts that were really interesting kind of around a bit about this risk taking mentality and the need to take risks, but also the need for somebody to step up and be excited around raising their hand and saying, Hey, I'm willing to put myself on the line for this. And I think what ends up happening is, and to kind of give the creatives at the brand side some credit is that they don't have as long of a leash either. And so you have people who are less willing to go out on a limb, try the crazy thing, do the new thing, and people that want to just do more of the same. And so she was kind of speaking about this homogenization of what we're seeing. And so I feel like there's a bit of this cycle happening where because of Covid and because of the fact that, well, not because of Covid, but because of the effects that had on the world and the economy, people don't want to lose their jobs and people want to play it safe. (11:04): And I think I noticed this a lot as another example, you have the creative agency that they land the dream client, they land the Toyota or the Apple or whatever, and I'm sure that they got the client by pitching them a rad crazy idea that was full of just ingenuity and inspiration. And then maybe they release that one and they became the agency of record or the agency that they would hire. And the work got more and more stale over time. And this is a tale as old as time because they don't want to take those risks to then lose the client. And I think that on the clients and people are just taking less big swings because they don't want to miss, so there's less home runs.", "token_estimate": 515, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "09:39", "end_timestamp": "09:53", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "4802ca9c-7dfb-440e-b2f4-44a85c3895ed", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 6, "content": "Cole Heilborn (11:50): I don't want to make this question sound like I don't appreciate the importance of data backed creativity because that's super important, but has the reliance on data devalued our appetite for risk?\n\nChris Burkard (12:04): Yeah, that's a tough one. And I think what you're kind of getting at is ROI like return on investment backed by metrics or backed by analytics. And for maybe anybody who's listening to this that doesn't know is analytics are the backend data that you can find on any website or anything that aggregates information. And I would say social media is one of those places where data is super important. Data can help inform the client a lot of information. I find myself on both sides of that where I'm sort of the one maybe leveraging my own channels for that, but I'm also the one creating work for a brand for their channels or creating work for a brand for somebody else's channels. Now I think it's super important, but I would absolutely not say that it's the only metric. And it's really tough to me where I pour a lot of energy and effort into this idea of all of that social, digital, blah, blah, blah, all that's important. (13:09): But at the end of the day, if you can get 300 people into one of your brick and mortar stores to have an event where those people had a physical experience, they're going to be consumers for life, they're going to be people that preach them, the good word, they're your followers. And to me, that should be the end goal. And I feel like there's so much emphasis nowadays placed upon just how much can we fill the garbage can, the never ending garbage can of social media. The appetite is endless. It's like it doesn't matter what you did yesterday, it's all about what you're doing tomorrow. And so I guess when I think about personal projects or the projects that have been really meaningful for me, they usually look like this. There's kind of a three-pronged approach. There is the media, there is the social media approach where you're telling a story in real time. (14:03): It's really cool, you're reaching millions of people or hundreds of thousands or whatever, and that's great, but those people, maybe they're not actually purchasing or consuming or whatever the goal is. Maybe they're not taking the product, but they are tuning in. And then you have that second tier, which is like maybe you create a film or a zine or editorial in a magazine and less people see it, but it's a bit more intimate and those people are more invested. So it's a little bit more investment, a little bit more investment. And then the people that show up at your store, the 200 people, the 300 people who see a film screening or they see, I don't know, maybe there's a new athlete that you're sponsoring or a new spokesperson who's giving a little presentation or a slideshow. This is kind of like we're talking about the outdoor sports industry. So I feel like I'm kind of trying to circle around these types of activations. Those people are so valuable to you, and those are the people that I would personally, if I was a marketing director, I would be there at the event looking at every person saying, does this deck that we've circulated around our company that reflects our core audience, do they look like these people that showed up? (15:21): And sometimes they don't. And I think that that to me is a big red flag. And if they do, that's a big sign of success. Do you know what I'm saying? It's kind of like the companies and brands spend so much time ideating and trying to understand who their audience is, who is our demographic. I think that one of the biggest values that I have had in my life has been trying to do film screenings and do speaking events and just trying to put myself in public settings for companies or for myself. I'm sharing my own film or whatever and being able to actually meet people and introduce myself people and connect to people that I know engage with me. And so I guess what I'm getting at is that the importance for a brand to do that is tenfold so much more. And it informs you as to who is your audience in real time, not based on analytics, right? (16:18): Because this is the issue I have with data, and I know that I'm kind of taking the long path around to answer your question, but the problem with data is that you can look at Instagram every day and be like, oh, we've got 46% female and 27% male, and these are their age groups and this and that, but does that mean that those people are consumers? It doesn't mean that you actually have to people, which is kind of a problem sometimes in this industry where I feel like we're getting more and more separate from who actually engages with us. And you need to be able to interpolate that data in real time. And I get really excited about that information. I get really excited, and I love when I meet somebody where I'm like, wow, I never would've thought that that was a consumer of this brand or my brand, but there they are. They're walking out the door with something of mine that I'm selling or a company's a brand's jacket or book or shell or whatever. So that information to me needs to be taken with a grain of salt, I guess.", "token_estimate": 1304, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "11:50", "end_timestamp": "12:04", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "def76eb7-8492-4e36-be7d-ebc8e7f5550c", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 7, "content": "Cole Heilborn (17:27): How important is the audience when it comes to developing creative? I guess in my perspective it's paramount, but how have you seen the importance of audience alignment play out in the real world?\n\nChris Burkard (17:41): How important is the audience to the brand's kind of ethos or more just the relationship they have with them? Is that,\n\nCole Heilborn (17:49): Well, as a brand, if you're going to make something, you want that thing to resonate with the right people. And finding that frequency I think can be tough sometimes. That resonant frequency,", "token_estimate": 145, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "17:27", "end_timestamp": "17:49", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "3523fbbb-e21a-474c-bcf2-bb5d663f1986", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 8, "content": "Chris Burkard (18:00): You're using some really loving words to describe this, but I would say it's absolutely crucial. And honestly, hopefully there isn't any jadedness coming across here, but I definitely see more brands than not who the products that they're making are not informed by their users, right? By the people that are buying the product. It's informed by somebody sitting behind a desk being like, oh, well, I'm going to ideate this beautiful piece that's my vision and I'm going to put it out to the world. And then when people don't buy it or accept it, they don't know how to because they're artists. And artists don't like that type of feedback because a lot of times the difference between a starving artist and a successful artist is usually validation of some kind. And so let me try to back this up here, but ultimately, Patagonia, I used to work for Patagonia. (19:03): I was a staff photographer for them. Early in my career I was on retainer and I worked under Jane Seaver. She was an incredible photo editor who was there for 28 years. And Patagonia really taught me the value of shooting commercial work. It was obviously to sell clothing, but it was done in an editorial way. And actually that is the work that I would say attributed to being able to shoot for brands like National Geographic and whatnot, because it helped me to understand the decisive moment and not forcing it and letting things play out. But the point is, I remember vividly, I had this conversation with them, and this was outside of the photography side of things, but they said, we hire some of the best designers in the world. And oftentimes you can tell a good designer from a great designer, if they come in and a great designer will say, this pair of shorts is perfect. (19:56): The best thing I can do is nothing. I'll change nothing. That is me leaving my mark. But the problem is, is that people that are so intent on leaving their mark, making their name, making their change, despite maybe despite the kind of reciprocity of needing this change being there, they change it or they adjust it or they fix something or they alter something or they throw out this crazy color, whatever it is. And I guess what I'm saying is I feel like the brands I really respect and appreciate are usually the ones that are sort of aggregating that information based upon their audience. And you can see it I think very clearly, the brands who are on social media responding to people who have witty, witty captions, who put time and energy like this is what's funny is I'm not necessarily an advocate for Red Bull at all, really cool brand. (20:58): I love what they do for photography personally, but their social media is on point. And what I mean by that is when you see their captions and when you see what they write and what they share and what they respond, it feels like a real person. That person has a personality. When a brand has a personality, we care about it. And this is 2024, the entry fee just to get into the industry is that you have to make a jacket that keeps you waterproof. So when a consumer goes to North Face, Patagonia, whatever, mountain Hardware, they're not looking for a waterproof shell. They're looking for a brand they identify with and the brands they identify with, it's about so much more than the tech. The tech is great, the tech is cool, it lasts for a moment, and then it vanishes because at the end of the day, they all make something that will keep you warm. They all make something that'll keep you dry. You latch onto these brands because you feel like they're speaking to you, and they do that through the content that they create and what they stand for. And I think that that is something that's hard to track through ROI. It's hard to track through analytics. It's hard. It's hard to speak to somebody's kind of core values when you're making six second TikTok videos or advertising pieces that are short and sweet and not really don't have any substance. I guess", "token_estimate": 1002, "speakers": ["Chris Burkard"], "start_timestamp": "18:00", "end_timestamp": "18:00", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "d563f78f-5044-4212-88f7-5ad815a766eb", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 9, "content": "Cole Heilborn (22:33): Your observation about a good versus a great product designer, that's really interesting. Can that be applied to the marketing department?\n\nChris Burkard (22:40): Huh? I mean, I'm kind of speaking directly about the marketing department as well. There was years ago I used to do a lot more brand consulting where I would come in and when a new CEO would come in and I would help shape a photo department and I would do some presentations, and I stole a lot of my information from brands that I had worked with, pieces that I really liked and good art directors that I'd worked with and great product designers and line managers, et cetera, et cetera. And the thing that I always appreciated was how, and you'll probably relate to this, but there are some brands where the marketing initiatives come from the product team. And I feel like that is a little bit backwards. The product team is designing. To me, it's really hard to explain this without my charts and my graphs, but ultimately the way I always saw it is that there's kind of like a triangle or a circle and it can go one way or it can go the other way. (23:45): And a lot of brands, what ends up happening is when the marketing department is not functioning correctly, then what happens is that the marketing initiatives come from product as opposed to, and we're talking about kind of a specific type of brand that maybe has athletes and ambassadors or whatever, which is most brands nowadays. Typically, the best way that I have seen it work where it's not dysfunctional is that stories aren't told for no reason at all. If you create a product that's just like, what's the purpose? What's the point? Then the marketing department is now, when the marketing initiative is informed by the product, they're trying to force a story as opposed to marketing department is in touch with the athlete team or the ambassador team or whatever that is. These athletes are now telling the team managers what they are doing throughout the year. These are my big projects, my dream projects. They're informing the marketing department that is then saying, this is great. And then they are in touch with the product team. And what's happening is the product team is kind of going back and forth with the marketing department and what's happening is that then the marketing department is choosing some of these expeditions, activations, projects, whatnot, that will then support this product launch. Does that make sense? I know I'm not explaining it super well.", "token_estimate": 634, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "22:33", "end_timestamp": "22:40", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "16e1f21d-b5a8-44a2-a1c5-f858ed96a835", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 10, "content": "Cole Heilborn (25:18): So you've got marketing on one point of the triangle product on the other, and then athletes and ambassadors on the other.\n\nChris Burkard (25:23): Yeah, so it's like product is here, ambassadors are here, they're working together. They should be because the whole point is that the best product is usually informed by the people using it. You hire brands should hire product testers, ambassadors, athletes, whatever to use it. That's what makes it good. So that product is informed. And then what happens is the new product, it goes up to the marketing team and then the ambassadors or the athletes, they send their pitches, their ideas up to the marketing team, and the marketing team connects the dots as opposed to it all coming from here, going here, and then they're trying to splay it out. And this is why for many years in North Face, they had such a good program because what they would do is they would have an athlete summit and athletes would come and they pitch their ideas, they would talk to this little trio of basically decision makers that sat on their expeditions council. (26:21): And I'm not sure if I'm giving away any trade secrets, but a lot of times that expeditions council would be like, okay, these are the expeditions or these are the projects we're going to say yes to or grant money to or whatever. And obviously that would be supported then by the product. So they would come back and they would say, this is what we're doing this year, which product are you making that could feed into these different trips? Which of these trips would be wise for us to launch this future light or this or that or whatever. And that is a much more functional method, I think, of informing the public in a cool way why something is made. Now, granted, there are other brands maybe, I'm not sure, but maybe Cotopaxi, where they don't really operate in that space with athletes and this and that. (27:18): So they have to kind of do it a different way. And I'm not saying this is the only way, but I am saying that I think that there's a really, I see that as being more functional. And when I've been able to work alongside marketing departments that operate that way, it's much more clear because when you're trying to kind of force a story, when I get a brief or you get a brief and it's like, Hey, here's this new product, we need to form a story around it, you're like, okay, alright, what's the use case? What are the properties of the product that make it interesting? Is it a jacket that's got this crazy breathability and lightweightness? Is it a camp pillow that for side sleepers? I don't know. So yeah, obviously I know that we're, I'm specifically talking about these kind of I think 15 to 20 core brands that operate in that way, but I know that there's a much broader use case in this industry.", "token_estimate": 712, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "25:18", "end_timestamp": "25:23", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "e990e889-61ab-4798-8b13-dd9f36a66671", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 11, "content": "Cole Heilborn (28:13): So is that what leads to maybe some of the lack of clarity around briefs or direction for creatives? Sounds like it.\n\nChris Burkard (28:20): Think so. I think it's actually a very linear, when you're like, oh, I'm going on a trip to document these people doing this thing and they're professionals doing their job. And in this position, I just have to kind of be there in the right moments at the right places. And the deliverables are telling this story. Now it becomes a bit more tricky when we don't really know. Maybe if they don't know where it's going to end up, that's tough because then you're\n\nCole Heilborn (28:51): Talking like deliverables.", "token_estimate": 169, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "28:13", "end_timestamp": "28:51", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "11adb97d-7e0c-4b15-b46c-f5bc70973946", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 12, "content": "Chris Burkard (28:52): Yeah, that's one issue I find a lot. We don't know where it's going to end up. I'm like, okay, well are we shooting this for YouTube? Are we shooting this for social media? Is it vertical? Is it horizontal? Is it, and that becomes its whole own complexity. And I think as you notice, probably too Cole, the deliverables have now doubled triple because you're having to do cuts in every variation. And I mean, not that the general public doesn't care about this, but what works for Instagram stories doesn't work necessarily for vertical Instagram because it's cropped and then one is four by five, one is 16 by nine, and then you've got your normal vertical format and then you've got YouTube. So deliverables become really big and they become pretty complicated very fast. And I tend to try to whittle those down to maybe what we feel like is possible. (29:47): But with that, I don't have a definitive answer as to why I feel like it's a complex time. But I think that part of it is kind of chasing trends, which is a part of it. And we all do that, trust me. I mean even myself a lot for sure. Brands, everything, chasing trends, trying to kind of catch up to the next trend, which is tough. That's a really tough position to be in. And then jumping around is really tough where you're like, oh, we tried this didn't work. Let's try this now. Let's do this. Now we're going to do a long form film now we're going to tell a story now going to, and I feel like from the consumer's perspective, the consumer's so smart these days. They see through that. They see through it when a brand is not authentic or they're trying to glob onto somebody's authenticity because they don't have it. And I think that there's nothing more painful than working on a project and feeling like you're making something good, but knowing it's not going to perform well because of the execution of how it will be put into the world. And just last comment is I feel like nine times out of 10, it's the delivery of it that really informs and the strategy around the delivery that really informs if it will be successful or not.", "token_estimate": 532, "speakers": ["Chris Burkard"], "start_timestamp": "28:52", "end_timestamp": "28:52", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "6ef40fc6-3ebc-4294-b2e1-fefda512e300", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 13, "content": "Cole Heilborn (31:11): So we started this by talking about the changing role of creatives. Do you feel like that piece of it, strategy and distribution, is that responsibility being shifted to creatives regardless if they want it or not?\n\nChris Burkard (31:23): Absolutely. I would say so. I mean, I think in good conscience you could keep your mouth shut and just be like, cool, let's do it. I'll take the job. But I don't know that there's anybody personally who wants to be hired simply because they have a camera and know how to use it. I think people want to be hired because they're creative, there's collaboration, it's exciting. You're the best at what you do, and we want you, Cole, because you bring this to the table. That's the validation and what you want to find or hear when you're being hired for a job. And so with that, I think that we feel the need to speak up maybe when we think that something might not work or might not hit the mark. There was a time in my life and career where I was probably a little more sheepish and would just be like, sure, whatever. And I would shoot the job and then it would flop for them or whatever, but I didn't feel responsible. Nowadays I feel more responsible. And I think the reason I feel more responsible is the reason everybody feels more responsible because you want to share it. I don't know how many, can I ask you? Have you done jobs that you've never shared because you're embarrassed?\n\nCole Heilborn (32:39): The portfolio has been Yes. Well, meticulously crafted.", "token_estimate": 383, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "31:11", "end_timestamp": "32:39", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "27480d9c-10dc-4018-971d-3f535380703a", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 14, "content": "Chris Burkard (32:43): Totally. And so me too, I have done work that I have shot that I wasn't particularly excited by. It might've paid well, but I kind of walked away and washed my hands of it. And I think that anybody who has a good conscience feels like they owe those brands maybe a bit of their 2 cents around if it's going to work or if it's not or whatever. And I also think that there is more room for that now because you start these conversations and then you realize that there's a lot of indecisiveness or there's a lack of definitive answers around what the goal is. And that leaves, what ends up happening is that there's a ton of ambiguity and there's a lot of room for error. And as I said before, I don't want to be beat onto a dead horse, but it's people not wanting to take the blame if something doesn't work out. (33:39): Everybody wants to take the blame if it's super successful and it was that crazy wild idea, but nobody wants to write in stone what the success looks like. And then if that doesn't work out, then somebody has to take the blame, which is a bummer. I'm not trying to stand on some moral high ground, but I think that why, to answer your question, the path of creatives is now more synonymous with creative direction and or kind of more agency type work too, is because we want to share it, we want to share it with our audience. We're proud of the work that we're doing. And until the last, what, 10 years, we've never had that opportunity. Now with social media, that is a part of it. Also, I would say that I'm put into a little bit of a tricky situation sometimes because I do know my audience really, really well. (34:39): And so when I have a brief that comes through and in the early days of social media briefs, I think it's different now, briefs would come through and it would kind of be cut and paste. We want you to write this, we want you to say this. And I'd be like, guys, never in a million years would I communicate this way or this is cringe, right? This is not me. This is not authentic. I think now all this emphasis is placed on authenticity. It's now a buzzword, sadly, but it's because they want it in your own voice. And so with that, if I'm doing a job that's sort of hybrid where I'm shooting something, but I'm also sharing something, that's the situation where I'm like, yeah, I'll shoot it for you, but if you want me to share it, I absolutely need to have some creative control. And so I think that that's part of the role that we're in nowadays a little bit. And I know that my situation is a little unique, so I don't want to say that this is the industry standard at all, but I do just want to clarify that a little bit.", "token_estimate": 674, "speakers": ["Chris Burkard"], "start_timestamp": "32:43", "end_timestamp": "32:43", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "2bb7e468-56f1-475f-9693-221488239e53", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 15, "content": "Cole Heilborn (35:44): What's the biggest opportunity you see for brands amidst all of this upheaval and change?\n\nChris Burkard (35:50): I mean, I think the biggest opportunity is I think the opportunities are kind of endless really. I feel like through the noise to me, really exciting stuff rises to the top. There's always been a tried and true method of what's worked over the years. And I guess I feel like the brands that get me excited are the ones that are still putting emphasis into that physical interaction, that grassroots, let's get people to be in a place and experience something real. When I see a project personally, I saw on social media, I followed it and then it had a film premiere online or whatever, and then there was an activation or a zine. I'm like, dude, I'm in. That is cool because giving something to the consumer, they're providing something, a service or information or inspiration or creativity or a tangible item like a book or a zine or a guide. That's what gets me excited. (37:00): Patagonia's wear initiative, which was actually started by a friend of mine, was probably one of the most powerful things. I'm a big student of brands. I love understanding the process and stuff, but now I don't know a single brand of that size that doesn't have a Rebi or a so shop. And what I'm saying is that they all copy Patagonia's war wear initiative, and there's nothing wrong with that. That's a great thing for the world, great thing for the environment. But all I'm saying is that there are opportunities for brands like that to do something new. There was a time when that would've been seen as maybe suicide by a brand to allow people to get their stuff fixed for free and then do a tour around the US and Europe and whatnot where you're fixing people's stuff for free, but that makes people want to jump in bed with them even more, if that makes any sense. And now what you see is every other brand copy paste that same thing, that same initiative.", "token_estimate": 496, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "35:44", "end_timestamp": "35:50", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "a366a51b-17cd-4a4d-87df-a08896208ffc", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 16, "content": "Cole Heilborn (38:08): Do you feel like some brands are paralyzed by all of the opportunity? I call it the Netflix paralysis. You log into Netflix and there's so many things that you can't actually pick a thing. Do you feel like brands might struggle with some of that paralysis because there's so much that they could do?\n\nChris Burkard (38:26): I struggle with that too. I don't know about you, but I get overwhelmed pretty easy. If I walk into a grocery store, I'm like, oh my God, there's too many options I need to go into am PM or something like that. I feel that, and I do think that that is overwhelming. I think as a young brand, I really appreciate brands that are small and that kind of pick a lane and go for it. And I think that just the creative advice that I would give to young photographers is you don't need to be everything to everybody. There's never been a single editor at a magazine that's hired somebody worth the money or worth their salt because they were good at decent at portraiture and animal photography and weddings and action sports. They hire you because you're a specialist and because you're the best at something and this is the reason why you would hire Paul Nicklin to shoot under Antarctic Ice the best at it. (39:28): So I thought long and hard about that in my career, trying to almost silo myself a little bit. And then once I felt like I had a good bearing on what I was really good at and competent at, I felt like then I could branch out into other portfolios. And what I'm getting at here is that brands like Seeger, a young California surf startup kind of brand, it has a cult following. They know their lane, they know their space. Brands like Rourke as well also, they know their lane, they know their space, they know their audience really well. And you see these brands that have had growth like this. And I'm not always saying that that growth is great, but when brands can manage it well because they care. I mean, I know these brands personally and who runs them because there's a handful of people that they care that they live that lifestyle. (40:24): What happens is brands get so big that, and I've been in this situation where I've worked alongside new CEOs, is like they're so detached from who works for them. They don't know them, they don't understand. When you have a 2, 3, 400 person employee roster, that becomes really hard to manage. How do you create continuity? How do you kind of all align? And I do appreciate when brands kind of know who they're talking to. And I think that that is always an important thing to stop and pause and realize that maybe taking a step backwards to recognize that and sort of refine your lane is important. I see this nowadays a lot with maybe some of the, I'm trying to share a perspective without pissing anybody off, but I see this a lot with a handful of the pointy end of the spear brands, if you know what I mean, the top (41:25): Where they're really trying to appease a number of audiences that maybe don't see eye to eye. You have your core audience that doesn't feel seen because now you're trying to appease this fashion audience and then you have this fashion audience that wants to wear the clothing because the brand is core. And typically what happens, and I've seen this so many times in the surf world where you have big, huge brands just crumble, topple, and it is crazy when you see a juggernaut that seemed like they had it all figured out, just crumble. And I think what's tough is if you totally alienate that core audience, you lose all of your authenticity not to throw it back at 'em. But that's what happens, right? (42:20): But if you lean too far into that core audience and you don't invite other people in, that equally becomes really painful. And I know I'm on a tangent, so I'm really sorry, but I do that sometimes and I loved the question and I do feel that paralysis situation. I think that you have these smaller brands who to bring it full circle, they see what happened and they're like, whoa, we want to be even more specific, a little more hyper specific at the start at least because we don't want to go the route that they did or they did.", "token_estimate": 1046, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "38:08", "end_timestamp": "38:26", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "36f9bfde-2a63-40e8-85cb-a8b41ffe595e", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 17, "content": "Cole Heilborn (42:55): Has good creative been commoditized? Does it have the same value as it once did?\n\nChris Burkard (43:00): No, I don't think so because well, that's a tough thing because you can, who's to say, right? Because there are times when I have argued that point and then there are times when I've been wrong. I think a part of being in this field long enough is you realize when you're wrong. I mean, there are times when somebody could go and shoot something that you or I did with all of our toys and all of our tricks and all of our this and that. They shot some with their phone and it performed better. And that's really tough. And honestly, I feel, I really feel for people in marketing departments who are like, well, who do we hire? Do we hire this person who's just really good at making things nimble and easy and quick and maybe it's going to cost one 10th of the price, or are we going to use this production company that's tried and true and tested? (43:54): And I think that it depends on, depends on the type of work that you're creating. And if it's long form content that has a storyline and a narrative and an arc that's really important that you work with somebody who knows and gets that. If it's short and it's small and it's simple, why not take a stab, take a risk. But I don't think the value is there to what it once was for sure. And just the budgets aren't there. And I will say I think it's a really hard time in the outdoor industry right now personally, just not saying personally, but just from everybody I talk to and me personally, it seems like it's a tricky time.\n\nCole Heilborn (44:35): So you mentioned you get overwhelmed. Does all of this change overwhelm you? And if so, what are some truths or some things that you hang onto to try and help you personally navigate all of the change that maybe others creatives and brands could latch onto as well?", "token_estimate": 476, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "42:55", "end_timestamp": "44:35", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "c857209a-6d14-4494-8081-ab9e6f20831f", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 18, "content": "Chris Burkard (44:54): That is a great question, man. That is such a good question. I don't think I've ever been asked that one. I sort of have those truths within my personal life, like my North Star. Why am I doing what I'm doing? What's my thesis? What's my mission statement? I feel like the best way to answer that is to say that I try to remind myself that if I don't align with the brand personally, if I wouldn't go out and buy those clothes or subscribe to that magazine or whatever it is, or if I don't know their mission statement, then I probably wouldn't consider myself the best person to work for them. And what I mean by that is when I've taught workshops in the past and there's young photographers and I'll always ask them the same question, how many of you want to work for Nat Geo? And everybody raises their hand and I'm like, how many of you know their mission statement? And nobody can repeat it.\n\nCole Heilborn (45:50): I think I've seen these videos of you doing", "token_estimate": 247, "speakers": ["Chris Burkard", "Cole Heilborn"], "start_timestamp": "44:54", "end_timestamp": "45:50", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "59d6b35f-64c9-4015-8d17-5133510103a2", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 19, "content": "Chris Burkard (45:52): That. And it's simple. It's like if you want to work for them and if you want to create something good for them, then you need to be a student of that company or that brand. I find myself doing the research, spending the time and being a creative that I feel if a brand is hiring is going to kind of do his due diligence to understand their audience, I'll spend a good couple hours just scrolling through their Instagram feed, looking at what people are responding to them, look at how they're communicating back and forth because maybe that's the linchpin, that's the issue. I take it upon myself to do a little bit of research to kind of understand and maybe just market research to sort of figure out what's missing, right? Because although I'm asking them what does success look like? I'm also asking that of myself and I'm trying to understand that. (46:46): And I do feel like to me, inspiration is always king. That's just what I've always felt. If a brand can inspire me, I want to support them. If a brand can get me off the couch, I want to support them. If a brand does something bold, I want to support them because I want to reward that behavior. Does that make sense? And it's hard for me to say if this is just a me thing or if this is what everybody feels. But even the other day, Mamu did that ad campaign where they're like, we're not a streetwear brand. And despite what people feel, I'm like, that's a bold statement. I love that. That's cool. (47:30): You got to respect that. Yeah, you got to respect that. And I think that that is exactly what I'm talking about. And with Patagonia, the choices they've made for the environment, people glob onto that. When you wear Patagonia clothing, you feel like you're representing the environment in some way. And so I think that brands nowadays, there was a time when it didn't really matter what you wore as a consumer. I'm a consumer, you're a consumer. But nowadays, I don't want to get too serious here, but we kind of share publicly with the world how we vote, what we care about, what our morals are, what we love in life based upon the brands that we wear, based upon the clothing we wear. And that's how it's always been. You have big Nike hat, you're an outdoor, you're a runner or whatever. And so I think that that is universal, I guess. And that is something that will always say the same. (48:29): I really consider and think about my place within that world in terms of creating advertising, meaningful advertising. I ask myself often weekly, what does that mean? What does it mean to create meaningful advertising that not only made its mark for the brand or turned the page, but also I felt good about? And I think that looking back at the jobs that seemed to hit those marks, the universally, it seems to be that when something is inspiring or when something tells a meaningful story that is interesting and it's story-driven story first, I tend to feel like that's really successful. But then again, that's also what I'm passionate about. So I have bias. Sorry,", "token_estimate": 767, "speakers": ["Chris Burkard"], "start_timestamp": "45:52", "end_timestamp": "45:52", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "e77e8a7a-e85b-44c9-98eb-524e523c25d6", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 20, "content": "Cole Heilborn (49:19): We all do. Any last thoughts that you want to share with the audience before I let you go?\n\nChris Burkard (49:24): Man, I don't know. I really hope that young creatives out there search for good mentorship. And I would say that I think that in and of itself will really help the creative space just operate more functionally and more fluidly. And I remember when I was a young guy coming up in this space as a photographer, trying to get advice. There was a couple of people that took me under their wing and really helped. And there was a couple photo editors, Pete Terrace, Jane Seaver, Patagonia, who made all the difference. They changed my life because they gave me harsh feedback. This sort of answers maybe one of your other questions in a different way, but the way in which I think brands get more of what they want is by being willing to offer that harsh critique, that feedback. And there's nothing more painful than when you shoot something and you never see it go live or you never see it come to fruition. (50:34): And having to write that email to be like, was there something wrong with the work that is a vulnerable email to write? And it's not fun. And I guess what I would say is that there are times where I really would have just been appreciative of a little bit more critique, a little bit more feedback, a little bit more dialogue between me and the decision makers. There was a creative director, a marketing director at North Face I worked with for a number of years who was just so good and so honest and very much like a bring you in, we're going to figure this out kind of thing. And I loved that. His name was Landon, he was a great guy. And there have been people over the years who have kind of helped shape who I am. And I guess what I would say is I really want people in that role who are strong personalities, who are not afraid to call it as it is and who are not afraid to maybe bum somebody out if it means that collectively the work is better. (51:41): Because I would rather leave maybe my feelings a little bit hurt, but knowing that we got the job done and that I grew from it than being disillusioned to the fact that I nailed it. I nailed it for the company or for the brand, but it wasn't what they wanted. And so I think that that kind, that's a full circle thing. Photographers need to look for mentors and directors and whatever camera ops, they need to look for mentors. They need to be able to take good critiques, they need to be able to take good feedback and then inversely the brands, they need to be able to offer good feedback and they need to be able to offer harsh feedback sometimes because that's what makes the industry better. That's what makes it grow. I have come around sometimes done a job that was okay, lackluster, and then the next time I nailed it and it happened because they knew that I was learning and growing and they didn't just write me off and they helped me grow. And I just want to see more of that.", "token_estimate": 751, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "49:19", "end_timestamp": "49:24", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "c78303a0-5637-4406-95e8-dea11c3eac9b", "episode_id": "77a9bd4b-d319-4d57-b33d-0e3452f2e9d0", "cms_item_id": "68225dfc7bb476527f8c495b", "chunk_index": 21, "content": "Cole Heilborn (52:42): Beautiful. Thanks, mark. Chris, thanks for taking the time to share your thoughts. It's awesome to hear your perspective and your insights. Thank you,\n\nChris Burkard (52:49): Dude. I could chat with you all day. Honestly, I love what you're doing. Love your podcast. I think I know this is not your core job, so I just want to say I appreciate the time because I think that it has been an amazing tool. The amount of people that I've forwarded it to, sent it to just to say, Hey, this gives you a good pulse on the industry, and even just knowing that other people are feeling the same way that you and I are or other marketing directors is really helpful.\n\nCole Heilborn (53:16): Appreciate it. That keeps me going.\n\nChris Burkard (53:18): Yeah,\n\nCole Heilborn (53:20): It's a slog as you know, but I think every conversation makes it worth it because you get to meet someone, you get to learn that much\n\nChris Burkard (53:27): More. I totally agree.\n\nCole Heilborn (53:28): I'm sure people can find you on the internet somewhere. Is there anywhere you want to point 'em specifically?\n\nChris Burkard (53:34): No, I'm out there. I'm easy to find and I'm always down to chat and love a good chit chat around marketing, projects, jobs, and whether it's a young creative or a seasoned marketing person, it's always fun. I love connecting people in this industry.\n\nCole Heilborn (53:52): Amazing. Chris, have a great rest of your day. Cheers. Bye. Thank you for listening to this episode of the Backcountry Marketing Podcast. Please share it with a friend or leave us a review on Apple. ‍", "token_estimate": 402, "speakers": ["Cole Heilborn", "Chris Burkard"], "start_timestamp": "52:42", "end_timestamp": "53:52", "podcast_index": 192, "episode_name": "EP: 192 Navigating Change: Chris Burkard on Creativity, Risk, and Authenticity", "slug": "navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "web_url": "https://www.portsidepro.com/podcast-feed/navigating-change-chris-burkard-on-creativity-risk-and-authenticity", "guest_name": "Chris Burkard", "guest_title": "Adventure Photographer", "categories": ["creative", "brand"], "short_description": "Chris Burkard shares his unique perspective on navigating the constant changes shaping the outdoor industry, creativity, and marketing.", "podcast_length": "54:08"}, {"id": "dcf146c0-3c88-4d89-915a-77866f538c3c", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 0, "content": "Jax Mustafa (00:02): Have that positive mindset, but just it's scary. It's really scary. I still wake up scared half the time. I want to do such a good job and I want Arum to be so successful. And I think it's just this balance of creating your toolkit with yourself of how do I manage that high-paced environment? How do I create a system around me that helps external, that helps me kind of level back up and stay positive and confident?\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing podcast. My name is Cole Hoborne and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo, and today I'm sitting down with J tfa. She's the VP of Marketing over at Arum. How are you\n\nJax Mustafa (01:14): Doing? Great. Thanks for having me.\n\nCole Heilborn (01:16): Yeah, how's your day going?\n\nJax Mustafa (01:17): It's going good. Very busy, but I think that's normal in the startup small business world. Do you think you're ahead at 7:00 AM and then by time, is it almost four? You have 50 emails you even read, and\n\nCole Heilborn (01:33): Sounds like you guys are moving pretty quickly over there. How long have you been with the company now?\n\nJax Mustafa (01:38): Let's see, I started in November and at that point I was guess legitimately the only person on the marketing team. And then I've hired three employees, so head of brand, head of digital, and then head of paid, and then also marketing coordinator. So we're this big bunch. It feels like we've been together for years and it's only been months.\n\nCole Heilborn (02:03): Yeah, I think there's probably something about that pressure cooker environment where it breeds a certain level of connection and relatability amongst the team.", "token_estimate": 552, "speakers": ["Jax Mustafa", "Cole Heilborn"], "start_timestamp": "00:02", "end_timestamp": "02:03", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "78819b44-cc78-4e9f-ad23-b57c78729029", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 1, "content": "Jax Mustafa (02:14): Yeah, for sure. Or you think about a program and you're like, oh wow, we signed that agreement two weeks ago, but it feels like it was like eight, so it's just high pace.\n\nCole Heilborn (02:26): Well, I'm excited to have you on the show today. We're going to dive in and start talking about really how to build a marketing plan from Ground Zero. Before we get in, I'd love if you could give us a little bit of a background on Arum and on yourself, but Jax, you've recently stepped into this role with the company and have really tried to figure out how to go from zero to 100 pretty quick, and I think a lot of folks out there are in similar positions and I'd love to learn some of the lessons that you've been learning as you've been exploring this for the last few months now. So I'd love if you could kind of kick us off, introduce yourself and introduce the company.", "token_estimate": 223, "speakers": ["Jax Mustafa", "Cole Heilborn"], "start_timestamp": "02:14", "end_timestamp": "02:26", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "ca06c48f-ad7d-4169-858b-8d9585d1818b", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 2, "content": "Jax Mustafa (03:09): Hey, sweet. So I guess on my end, in the world of Jack's professionally, I have kind of been on all sides of outdoor space and retail. So started out with Lucy Activewear, actually front end managing a store at that point. There's only nine stores I think when all was said and done, they had probably hundreds and it figured out that I liked marketing through grassroots marketing, store design, things like that. And so I went from there to Crocs and headed up retail marketing and same thing, I was like, I think our marketing team had eight people. When I left there was 85. And so it was just this process of wear tons of hats in the retail marketing phase and push our campaign out to all of our big box retailers and beyond. And then dipped into store design actually, and did a few flagship locations with my colleague and then from there ended up with Native eyewear. (04:10): And so kind of similar to Arum, Aras, a little bit more high paced even, but it was right at the acquisition of Cross Optical Group. And so I was given this budget and basically was the new marketing department for Native eyewear, and I think the head of sales is new too. And we were like, all right, let's reboot native. And so got to build every facet of the marketing program and realized that that was kind of my sweet sauce, that was my expertise, was to really come in and either overhaul or redo a brand, find out the pieces that were carrying over in the native space that was just their product and relaunched the entire marketing program. From there, I ended up on that tangent of am I small business or am I corporate America? What's my next move? And I ended up dipping out and starting my own marketing agency. (05:14): And so I had nine brands right from the get go and helped smaller outdoor businesses to find their way and build a marketing toolkit. And either I was their agency of record or I helped them with a certain portion, or sometimes I would partner with a bigger agency and help with a certain facet of their marketing department. And then actually stumbled a year later upon Stoked Roasters was my coffee company, but it was my childhood dream. And I found this spot in Hood River where I was part-time and I'm like, I'm going to do my coffee dream at the same time that I'm doing my coffee business at the same time that I'm running around the world chasing world championship. And so I opened Stoke Roasters in 2014. It ended up expanding to a coffee bar and Park City and then also shop and shop concept with the North Face in San Francisco. (06:14): And in late November of 2019, I ended up selling to some really anxious buyers that wanted to really expand the whole business. So got really lucky because I was right pre COVID. And so from there took a couple years to explore and running the mountains. And then I stumbled upon Arum last fall, and Arum is a desert performance gear company. We're starting with footwear, so fourth generation boot makers from the Timberland family. So Noah Sports, who's I would say he's a great grandson of Nathaniel Schwartz who started Timberland. He fell in love with the desert and he wanted to go ahead and create a desert performance company starting with footwear but with a twist to it. And that was to be very good to the earth every step of the way. So that meant not using the supply chain that could have been easy and shaking up the supply chain and creating the first 100% bio circular desert boot. (07:25): So what that means is that every single part of the boot has a proven path back to the earth, so you literally could check it out of your window and it will biodegrade. So that was really important to us. And moving forward, any new product that's in the pipeline, it's using circular materials so that we can stick to that premise. It'd be good to the earth. And I think along with that, speaking to the A piece and I guess almost entering into the Earth Week, world Earth week is every week for us. And so we are also very worried about climate. And so many outdoor companies will kind of put a hard stamp on offsetting all their costs through a certain business, et cetera, through the logo on their website. And we were like, we want to be game changers in the fight for climate change by actually taking action ourselves. (08:21): And so we are in the process of launching our cactus pair program, which we actually built a test farm a year ago of 250 prickly pairs and those also called cactus pairs. And it's a concept of this mission to plant a million and that they sequester carbon at an exponential capability, they feed people with their fruit and pads, and then they take way less water to grow like drops compared to if we were to go and plant tons of orange trees, you're pulling so much water that it's part of the crisis of the Colorado River doesn't hit the ocean anymore. And so how could we actually put a focus towards that and find a case of sequestering carbon where we're not taking away so much water, then what's offset? So Airman a nutshell I would say is desert performance impact and climate.", "token_estimate": 1280, "speakers": ["Jax Mustafa"], "start_timestamp": "03:09", "end_timestamp": "03:09", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "27861672-9664-4595-a997-28039bb4e35f", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 3, "content": "Cole Heilborn (09:29): Wow. How many other products are out there that are fully biodegradable? That seems fairly unique.\n\nJax Mustafa (09:35): It's very unique in the hiking space. I don't know of any, I know some products like Allbirds or some folks like that are trying, but there's still pieces that are not hitting the 100% bar. So even when you think of an actual hiking boot, like a Merrill let's say, or even your trail runner, there's layers. And so those layers have to be put together with a bunch of glue and then even the top is glued to the bottom. In our case, we can't do that. And so we've handcrafted every single boot is handmade and the entire last is one piece, and then we've put in a cork foot bed which forms really well to your feet, and then from there we've sewed on the top. So the other thing that this does is let's say the length of your boot can last longer because let's say the upper is falling apart before the bottom, you can send it into us and we'll just repair it by sewing resewing and send it back. (10:39): So that way we're also helping with, I mean production obviously takes energy, and so it's in a concept of just, we'll, your boot. And then in addition, let's say you're done with the life of the boot, we literally will give you a label, you can ship it back to it, and we literally will give a new purpose to every single part of it. So we'll take it apart and we'll grind the outsole, the leather will be fertilizer, the metal will get recycled. The tencel, which is the breathable material on it, will get repurposed. So that's another part of our bio standard.\n\nCole Heilborn (11:21): So if I threw your boot out of my car, in your example, how long would it take for it to fully disintegrate?\n\nJax Mustafa (11:28): I think usually it's like hundreds of years. So in the right process, I mean you'd probably really have to bury it. It'd be like seven years, so hundreds of thousands to never two, seven. And so we've done some tests too in a lab, which you can see in our website where we've done a gif of it over a period of a few months and watch literally go away.\n\nCole Heilborn (11:55): Wow, that's cool. That's incredible.", "token_estimate": 546, "speakers": ["Cole Heilborn", "Jax Mustafa"], "start_timestamp": "09:29", "end_timestamp": "11:55", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "2cfd2d15-bbad-418c-be11-22c54c666b4c", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 4, "content": "Jax Mustafa (11:59): And also to focus so much on performance and the materials that we've used and the design that we have is when you think about the desert, it is the most aggressive, rugged, insane terrain that you're going to deal with. It takes terrain to an extreme. And I remember one desert running race that I did in the Tama Desert and for example, were just absolutely obliterated and shredded, and then they were playing dock tape all over 'em to still get by. It is just, it's a harsh environment because the desert's not just sand dunes. And so we want to be first in class a desert performance from how thick the leather is, but then it also has to be leather that can be streamed. So it's just like that whole shakeup of the supply chain I think was a five month process, I believe with Noah and this guy, Pete Lankford, who actually came from Timberland and I would call him a wizard of sustainability materials. So it's important for us navigate do it right, and there's a lot of greenwashing going on and I think it's kind of cool there's a bit of cracking down, going down on that, especially with publicly traded companies where they're looking at each step and really figuring out is this piece of the mouse pad really biodegradable and digging in and finding out based off of that you can say you're this sustainable. And so I think that'll clean up communication a little bit and it's pretty cool.\n\nCole Heilborn (13:46): Yeah, no, that is amazing. So I'm curious, you've got a lot of experience with a bunch of different types of companies, a bunch of different roles. What has been one of the challenges here with Arum today? Thinking about our topic, how to build a marketing plan from the ground up, can you provide a little context of maybe where the company was when you stepped into the role and briefly everything that you've had to do in the last few months?", "token_estimate": 473, "speakers": ["Jax Mustafa", "Cole Heilborn"], "start_timestamp": "11:59", "end_timestamp": "13:46", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "f69168ae-5bbb-4d94-9e5d-64e6ada49d11", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 5, "content": "Jax Mustafa (14:14): So I entered into my position at Arum at one week post launch. So it was a little bit of shit. And I basically came into, at the same time, I need to build a marketing plan and strategy. I need to onboard myself and figure out what's been happening or what's going on and then I need to deal with the day to day. And so I actually, I think within two hours of starting, I was on a conference call with Noah and his father who I highly look up to, I think he's one of my business heroes. And we were launching this, it's called a marketplace, but we were on with this really big brand and I'm doing this pitch of how they should be a part of our marketplace. I'm like, alright, let's go. So I think it's like it's a mixture of here's your budget and you need to literally make a massive marketing plan and you need to stretch your dollar so far for every part of execution and you can hire three people. (15:24): So I'm trying to figure out how to hire three people, manage this budget, figure out a plan and master the day to day. But I think if there's anything that my toolkit taught me, it's how to deal with that. Not really adversity, but juggling all these balls at the same time and going in headstrong and figuring out, all right, every day I've got to manage these four big categories. And eventually I think actually it felt like two months, but I think it was three weeks later, I had a marketing plan and I think four weeks later I hired my first person six weeks later, the second eight weeks later the third. And so it was just like, I mean it was 80, 90 hour weeks for a while, but I think that's part of a long time ago. I forget. I think it was when I was doing stoked, I was helping out somebody that wanted to start their own coffee company. (16:29): And through that kind of interview process or putting 'em under my wing, you figure out very quickly, do I have an entrepreneur mindset or am I more big business? I need very particular programs in one direction. And so I think through my process, my predecessor or the person before me that was going to kick off, the Arum marketing team came from a very big company and had some of the, let's say performance pieces and footwear, but big big company means your marketing team is like 20 people or more. And so you kind of become the person that you write debrief. So you do this high level strategy and then you delegate out and you're told what to do a bit more. Where in our world in startup, and I can't even call it a small business because we're already acting and performing in our marketing execution plan, big business, we're just aggressively on that path. So everyone on the team is at max. And I mean we're executing a program that's probably for 10 people and there's five of us. So I think it's being a master of multitasking and to lay out that plan.", "token_estimate": 715, "speakers": ["Jax Mustafa"], "start_timestamp": "14:14", "end_timestamp": "14:14", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "5fe9ce31-4750-4656-87d3-a882b9c53b3a", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 6, "content": "Cole Heilborn (18:06): You brought up a really interesting point that I want to jump back to and try to understand. So when you first stepped into the role, you mentioned juggling a bunch of balls and wearing a bunch of hats. It sounds like you've certainly, you know how to manage yourself in a high intensity, high stress scenario. But what was your mindset if you had to be candid, could you share how you were feeling during those initial weeks? I think a lot of folks are probably can find themselves in a very similar position where they're like, I have a massive list of things to do. I have one or maybe two people or no one to help me. And they're super psyched out. How did you manage that and how are you still managing that?", "token_estimate": 184, "speakers": ["Cole Heilborn"], "start_timestamp": "18:06", "end_timestamp": "18:06", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "28b88018-9006-4e1b-8c1f-2e656b473ec3", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 7, "content": "Jax Mustafa (18:53): I think the biggest thing is it really tests the confidence that you have in your own self. You have to believe in yourself because honestly, you're going to probably have minor panic attacks five to 10 times a day and that's straight up. And then there's maybe you're the person before you left things in a little bit of a soupy mess. So then it's like, I really want to perform and I want this company to launch correctly. I think also when you're the head of marketing for your CEO, you are your business partner and so you'll actually get caught up in what actually became probably the favorite part of, and we still do this a lot, I think we did this today for four hours, is be getting these mind meld strategy sessions and you really see how can you take all of our assets and tools and blow this up way bigger? (19:53): So those were probably the favorite parts of my day because no one, I would probably do that every day and when we're strategizing and planning and how do we blow up this business and we look back at the end of 2022 and we're doing something big here. And so I'd say those sections recalibrated me and I got really excited. And then I think because I was dealing with onboarding plus making a marketing plan, plus hiring people, I would say there are points that I panicked. How am I going to get it all done? It was 5:00 AM now it's 2:00 PM already and I'm going until my eyes pass out. And then you feel like you're not getting enough done. And so I think it's this balance of breathe, be patient, but also I use to-do lists and status documents like crazy to help me stay on task, but I think that it's going to feel like mass chaos and I think you just have to almost arm yourself out within the chaos it's around you. (21:03): And just at the end of the day I literally, I mean I have a sheet right now that's up that's 42 different things that are big initiatives that we're doing in our marketing plan. And every day I look at all 42 and I go, did I do what I needed to do today to move this pendulum forward? Did I get my team on task to do these things today in order to achieve our goals at the end of the year? And so I think that was one thing that was the easiest for me was like, yes, and if I didn't, you can't freak out. You just have to go to bed for a little bit and wake up an hour earlier. So I think that's been the biggest tool for me to stay on task with how much we're trying to achieve.", "token_estimate": 615, "speakers": ["Jax Mustafa"], "start_timestamp": "18:53", "end_timestamp": "18:53", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "07960df3-def4-40de-94f8-a5602db66095", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 8, "content": "Cole Heilborn (21:54): What are some of the differences between doing this at a small business level versus a big business level? You alluded to some differences, but I'm curious tangibly, what are some of those things that make what you're doing today so much? I guess two sides, what makes it tougher and what makes it easier Being a small business rather than a big business trying to do what you're doing?\n\nJax Mustafa (22:18): I would say what makes it tougher is that you can feel alone, you can feel overwhelmed, but I think the flip side of that is that your team is, I mean we're a team of nine and so you end up, I think especially Noah and I could probably just call him and be like, I'm in the weeds. Can you be a thought leader to help me out of it? So I think that mean a big company. It's like let's say at Starbucks, I worked at Starbucks through college. You can't call up Howard Schultz and be like, dude, I'm struggling. I mean that's also a way lower level job that I had, but I think there's just this, you feel like you're part of a family launching something really big. So I think the passion involved with that is so high and people are giving their all and wearing so many different hats that I think that passion keeps you going. And I think in the big business world, you have this robust budget really. I mean when it comes to marketing dollars amongst 42 different programs that you're trying to launch you, you've got a big piggy bank. And so I think the big thing, even when I was marketing agency for other clients, you literally compared to that $1,000, you have one. So it's like you've got to do a whole brand cam page shoot for a fraction of the cost and you need to get double the assets. (23:54): You become a mastery of stretching your dollar, which is really difficult. And because every cash burn to, and even when I was owning my own business and at Stoked Cash burn is this anxiety that you feel a lot as you're turning this pendulum of I'm putting in this time and I'm going to lose money at first and then I'm going to make money. When you're in that lose money At first you're just watching money go out of your bank account. And so I have a lot of passion for that for Noah and Arum. And so how is every dollar that I'm going to spend in the marketing department, how am I going to stretch it to get so much exposure and so much growth for us? And so I think that's a really big day-to-day challenge and you have to be ready to say messed up or say, I thought that would be good. (24:56): And you have to be ready to, I think I learned this from running around the world in desert races is when you get to that point of adversity, let's say in small business, it's that much more important to see the adversity skip to panic and go to the solution. And you just have to be that way and you have to coach your team to be that way because we're going to try stuff and we're going to F up and we're going to have to flip so quick and save those dollars so that you can fix it.", "token_estimate": 756, "speakers": ["Cole Heilborn", "Jax Mustafa"], "start_timestamp": "21:54", "end_timestamp": "22:18", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "0f6511ae-0240-493c-888b-026c7907ae70", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 9, "content": "Cole Heilborn (25:30): Yeah, I like that mentality. Stuff gets messed up, skip the panic and then find the solution.\n\nJax Mustafa (25:37): Got to, I mean, you're dealing with 42 different humongous ideas. And actually Noah said it best the other day. We were having a strategy meeting last week and we were looking at all these 42 things and you want to, and this is I think a lot, a big differentiator between big business and small when you're putting together an entire soup to net marketing plan is that big? It's like you can get away with bigger budget and we're going to do these four ideas this year and our campaign is leave only footprints, let's call it. And then the whole years around that and you have 30 people while doing crazy things, but it's very simple for us on our side. It's like we have to literally run and gun and go and if something isn't working, we have to be fast to fix it. So I notice that Noah and I probably Monday and Friday of every week, we literally look at all these 42 things and go, are we on the right track? (26:37): Should we change it? And your team, they got to be nimble because if they're so used to, hey, our social media campaigns would be this way, ready, set, go, and they're used to that and then it stays that way. You can't do that in small business. So in our world, it's like we're changing it, we're changing it, we're changing it. So you have to be really nimble and act fast and be ready to be like, okay. And it takes a certain character in your hiring process, it takes a certain individual that can fly around and use their piece of the toolkit, call it the digital marketing manager. She has to be able to just go, okay, cool, kill that campaign. Let's do this campaign and be okay with that and not get so stuck on something that it's like, oh, but this is my campaign.", "token_estimate": 459, "speakers": ["Cole Heilborn", "Jax Mustafa"], "start_timestamp": "25:30", "end_timestamp": "25:37", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "9418eb37-4b6c-40d7-9f09-eba4ebd1ecbc", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 10, "content": "Cole Heilborn (27:30): Do you have an example? I'm curious. You're talking about the various initiatives that you have and trying to be super thoughtful with money that you're spending. Do you have an example of a project that you've started where it did not go to plan and the money spent, you looked at that and you're like, well, shoot, I wish we could have tried that differently.\n\nJax Mustafa (27:51): I would say one of the big pieces that we found so far was a production. So we kind of did an overhaul to our brand identity literally a month and a half after launch. And maybe it wasn't an overhaul, but it was just really defining who is Arum, what's our brand, what's our story and voice? And so we had just onboarded a new marketing agency and so we were like, we need to do a whole new brand shoot to just get more gritty, get that performance piece more. And so we were dealing with, I think back in the day, shoots were a lot more expensive and I'm like, well, I call myself Scrappy Jacks. And so we went for a lower budget, but then it was a process of we had too many team members there and then there was creative who's a leader, was creative. (28:43): I think it made us really realize in a digital heavy world with a lot of production, it stressed our budget already for the whole rest of the year. And so now we're getting even more scrappy. I mean you look at different concepts, you'll go all the way back to the drawing board and be like, okay, let's take the whole budget and redo it. And should we be Patagonia model? We're literally, people literally submit stuff and you pay per piece or do we go super tier two three gritty and we swag people's shoes and they go and shoot a bunch of stuff, we give them little stipends and they shoot a bunch of stuff. And so I think on the fly, we thought we had our production kind of figured out for the year and we're completely overhauling and shaking it up and is it big campaign shoots and then all these smaller shoots. (29:39): So it's just like you got to fly by the sea your pants a little bit on that because you're dealing with six product launches in the fall winter and you need your bigger commercial shoots, but you're a scrappy young company and then you need all these fillers for five mediums of communication now. And you're in a video heavy world too, so it's like how do you get a bunch of B-roll? How do you make a bunch of YouTube videos? So I think one of the biggest things, highest level from a growth perspective in my career from starting with social media was hardly anything to now you literally hire a person to run five different platforms. Is there are all these different mediums that somebody wants to engage in your brand and how do you cover all those mediums? How do you make the budget to cover all those mediums? How do you become even video heavy when you're a startup? If you don't, how are you going to compete with everyone else you need to be competing with in the footwear industry? I think that's been one of our biggest challenges of content, content, content, scrappy, scrappy, scrappy, but great assets and good production. So that was a very interesting one for us.", "token_estimate": 795, "speakers": ["Cole Heilborn", "Jax Mustafa"], "start_timestamp": "27:30", "end_timestamp": "27:51", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "4388a245-f83f-49ba-87fd-a368bf9efb2d", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 11, "content": "Cole Heilborn (31:04): Can you share what your model looks like now, how you're trying to manage the needs for tons of content with a scrappy budget?\n\nJax Mustafa (31:13): Yeah, I think for us it's like you have your basic needs, which is your commercial campaign shoot, and that's the closest to the core. If you looked at this is our core consumer and then you've got rings of where else you need to expose and show that your product can even play, how do you do that? And for us you have those core shoots, but then I think for us it's strategize and look at how do we now take the rest of our production budget and we get, I call it tier two, but it's like, hey, here's a really small budget. I'll pay all of your travel and can you get us 200 shots and then we can use as on Instagram, we can use those on all of these heavy social media pieces that a bigger company, it would be like those are massive campaign shoots over and over and over again. (32:13): They're probably doing production once a week, but for us it's like, alright, hey friends, are you going to the desert and oh by the way, you're really good at production. Here's a small snipe and have a great trip. Can I have 300 shots? But I think that we did an experiment with that last week on a Kickstarter project we're doing, and it went really well. We slipped over to Moab and I drove there and an employee drove there and we literally probably got 200 shots out of it. So I think that it's in the world of production, it's those that are kind of thinking about how do I get all this content? How do I compete with a content heavy environment? I think it's finding your close network within two to three degrees and literally finding out who can you product seed and is there a good content even if somebody's just getting B roll and then we can edit it. So how can we utilize that? One of our employees is literally going on a really hard to get into river trip for a week and we're like, let's outfit everyone with sandals. So I think you got to be creative and grassroot with everything.", "token_estimate": 516, "speakers": ["Cole Heilborn", "Jax Mustafa"], "start_timestamp": "31:04", "end_timestamp": "31:13", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "00cb99e3-ab81-4380-99c4-c5913ee4e516", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 12, "content": "Cole Heilborn (33:48): So you mentioned that you stepped into the job and then three weeks later you had a full marketing plan ready to rock and roll and implement. How do you go, I'm sure you could talk a lot about how do you end up creating a marketing plan in that short amount of time, given all the restrictions that you do have. I'm curious though, if you could walk us through how you thought about your mindset to building the marketing plan and to actually getting something on paper that could actually then start to be used that seems like quite the task to try to accomplish and you pulled it together in just a short amount of time.", "token_estimate": 162, "speakers": ["Cole Heilborn"], "start_timestamp": "33:48", "end_timestamp": "33:48", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "451c66ce-9912-4d73-85ca-4a2b948c1b2d", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 13, "content": "Jax Mustafa (34:26): Yeah, it's a little intimidating and I would say we recrafted it probably four to five to actually we recrafted almost every day. But I think highest level, I think when you're in small business and you're trying to act like your big business and every single program, you're trying to blow it up. And so for me, my methodology has been I break out the entire world of a exposure and how I, and I don't even think about budget at this point. It's just like how do I build a really good brand, number one? Number two is all right, in the world of field events, how do I play in that space in a scrappy way, but a lot of exposure? Is it that I go and create my own events and get partners and sponsors or do I partner in on something? Then you go to pr, it's like how do I champion pr? (35:25): And because it's really important to get your word out there and for launches and so on, and then you just keep going one by one. How am I going to get my creative, do I get an agency or do I hire a bunch of graphic designers and what's the cost benefit analysis if I go one way or the other? And we definitely had a turn in that too. I first was like, I'm doing all graphic designers and I'm like, actually I'm doing an agency of record. So because I felt it was, so we're with this company called the Brand Leader and they're just, they're doing amazing. And so then it was put more effort towards a retainer and then you just keep going. And so my best way is, especially when I came in and this situation of maybe a fragmented marketing plan and I had to redial it at first, I tried to just redial what was there and then I was like, Nope, I'm clean slating the entire thing. (36:25): And so my strategy with this year with this plan was where is error at? Or maybe it's a category, we haven't done anything at all and how do we champion it this year? And so whether that's public relations, did we like where it was at, we felt we could do better. So we went on an interview process and now we feel like we have a team that can completely champion it across all areas that we want to focus on. And so I think that it's one by one going through that influencers ambassadors, we had some how do we make a team of, now we have a team of 12 that we're just launching to the community and maybe it's 25 by the end of the year, but we even decided to do that different. It was like being a pro athlete in the past and going through a process of athlete contracts for 20 years. (37:21): There was half a contract that I didn't really like doing. And so we were like, let's be different and let's slow our role just a little bit and champion ambassadors. And so the 12 people we have on it was, Hey, we feel you could be at tier one through three and for tier one, here are all these ideas of things that we would want you to do and based off of maybe you're really big on TikTok or you're really good at reels or whatever that is. And they made their program. And so then the get was there at a whole different level for their passion of what they're doing. So we literally took the time to do 12 different contracts, but now we have 12 people that are just going nuts, exposing the brand and are so excited about it. So I think it's highest level program by program, it's how do we champion it and then let's say climate for example, how do we do it different, right? (38:19): Oh, we could just go to renewable energy X, Y, Z company and call it good, but that's not arum. We want to give back to the planet all the time. That's a part of our ethos. So now we've got to build a whole program and how do we grow it and how do we get the involved in it? And so I think that was the only way to do it. And doing it in three weeks is extremely aggressive. I would not recommend, but I think now we have it set up where now we can look at in November, where are we at and where do we want to go? And so we use that huge deck as a way to look high level at where we were we get to and where do we want to go next and doing that amongst 42 different things.", "token_estimate": 1016, "speakers": ["Jax Mustafa"], "start_timestamp": "34:26", "end_timestamp": "34:26", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "3a267156-f525-4cc3-a6ef-5816b9d3d6d0", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 14, "content": "Cole Heilborn (39:12): I'm curious, how does your revenue goals fit into this as well? And we don't need to go into specifics, but I'm sure with any startup, with any business, your revenue goals are super crucial as you're slowly chipping away at that pile of money in your account as you're spending on all these initiatives, as you're working on these marketing on your strategy and all of your production and all of this, how are you thinking about revenue goals and factoring that into the things that you oversee?", "token_estimate": 130, "speakers": ["Cole Heilborn"], "start_timestamp": "39:12", "end_timestamp": "39:12", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "de8677d2-0915-42b2-9a97-e9c08bf4d174", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 15, "content": "Jax Mustafa (39:42): I would say there's two ways that you can look at startup and small business wants to become big business. So I feel like there was the stoke model. I was super scrappy. I literally, I think I did 12 jobs by myself, but what that meant from a revenue target perspective or with my formas and my investors and everything that I was doing is I expect my turn to be, it took five years and at that point I was all of a sudden way revenue positive. And so those were years me paying myself $0 running around the world as a professional athlete or second job, third jobs. So that's kind one way you can do it. Where we're lucky with Aram is that we have a platform where we are pushing, I would say our revenue. We're trying to go big or go home. And so where we're lucky is that we're building, I mean I have three employees and so if you just take marketing department and you look at, that's an investment, that's four salaries. (40:58): And so our biggest goal is how do we take this marketing plan and we get 10 times the revenue from it and still be on a scrappy budget, but still it's not, I guess stoked budget. So how do we take advantage of the opportunity where we're getting to maybe like, can we do this in one year? Can we turn this in two year? So how can we turn it faster? You're putting in a lot of investment not only in marketing, which is a big piece of it to get exposure, but you're also putting in product. We have four skews right now. We're adding six new products, so many skews to the lineup by the end of the year. And so even those are go-to market strategies for all those. And so I think in this dance we're getting the opportunity to maybe go for revenue goals that another small company, it would take them a bit longer, but it's still the pressure of we're shooting for the stars. And I think it goes back to, we were talking about this other day, we're going to do this Kickstarter, and we're really thinking, how many backers can we really get? (42:19): We're of course 3,500, we're going to be on the front page. But I think there's something that comes with that and it's to get the revenue goals that we're trying to get, which are extremely aggressive, call it, I don't know, 10 times your marketing budget or something. It's an all hands on deck process. It's very high paced. Everyone feels like they're in the weeds all the time and you almost just, at first you're uncomfortable with it and then you just have to get used to it. And then I think there's this piece of, everyone has their own version. My version is I'm not that spiritual, but I believe that thoughts are your feature. So if I put on my mirror right here, Erin's going to make x million this year, every day I'm looking at that sticky and I'm thinking, how am I going to do that? (43:15): It goes back to me talking about how I literally have a spreadsheet of all the 2042 things every day. It's like if I put in that effort every day, if I'm literally moving the needle on all of these things every day, the universe in my case can't deny me access to this revenue goal that I want. So that's how I believe, and that's what I try to instill upon my team is just go for gold and we're all here for each other. It's going to be hard and if we're going to fail along the way, but as long as we're doing this, which I think is normal, we may look back at the end of this year and be like, oh my God, we did it. And so that's kind of positive affirmations is kind of how I hit the really major goal.", "token_estimate": 881, "speakers": ["Jax Mustafa"], "start_timestamp": "39:42", "end_timestamp": "39:42", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "e0382a9e-1507-4dc7-b6c8-0a81bdb92edb", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 16, "content": "Cole Heilborn (44:09): Yeah, well said. You've mentioned this as we've been chatting, but I don't think we've actually officially talked about it, but I'm curious how your role as an athlete has equipped you for this job.\n\nJax Mustafa (44:25): Let's see. So I've been rank since I was a kid, went into track and field triathlons for 10 years professionally, found my love for the trails, which led me to a single day Ultra Runner. Had a lot of podium positions there, which then led to me doing self-supported stage races in deserts. And so I could say out of the team, I've probably been to more deserts in the world than anyone on the team in a major sufferer version. So these races are, you wear everything on your back to survive. So I was a part of the four deserts race series. I won all of them in one year and was a female world champion. And then I did an extra race on top of the four, which is called the Grand Slam plus if you do all five in one year. And so I became the first female to ever do that. (45:19): And these are races where it's a little bit different single day ultras, like you go through adversity, ups and downs every single time. But these are a little bit different where over a week you've got your food in there, so you're starving if you want to win, you have your safety supplies, sleeping equipment, they're just giving you water and a tarp to sleep under. And so you hit these lows that make you feel like you're going to die hands out. I remember I was in the Goby Desert, it was 135 degrees. My shoes were melting, so my feet were burning, I was vomiting and I'd run out of water and I'm making history as second place for the day overall outright in this 50 mile day. And no one had ever done that in these races as a woman. And I'm literally, the race crew comes by and if they see that much adversity, they may pull you, which would mean all those dreams were crushed. And I literally just kind of wiped my face off and I was like, I'm doing great and I'm pretending drinking empty water bottle playing mind games. (46:29): And then I mean, you finish, you win, and then you're training for the next one and your body is just all wrecked and the next one's in six weeks. So I think there's big things that I spoke to one earlier where it's just that I think that type of racing or any type of athlete background for an individual, it teaches you things of goal setting, of pushing the limits of believing yourself when no one else does of doing the superhuman. I'm known as Wonder Woman Jacks. So it's like doing these elements of going above and beyond, how far can you take your body when it comes to even work, how far can you take your mind? How far could you take a program? How far could you stretch a dollar? And the tenacity, passion and grit that has to come with it, especially at Arum when the pace we're trying to run. (47:26): It's exhausting, but it's like the coolest brand ever. I've never been honestly so passionate about a role in my life and I probably haven't ever worked this hard including my own coffee business because I'm so in love with the premise of this brand giving back to the world and the team is just really cool. And so I think in this case, it's like you could relate exhaustion in the desert and feeling like you can't move another step to one foot in front of the other, just one foot in front of the other, just keep going. And same thing, it's 10:00 PM you've been working since five, but you want to make this program all it can be. I think you have that same mindset and then you're dealing with adversity. I mean, my shoes melted, my feet literally got blisters. I still have to run 10 K to the finish line the next day. (48:22): That's rocks, that's gritty desert train. So do you have tape in your bag? No one else is allowed to help you out. So it's like, can you duct tape the hole to get through? And literally every step I was like, ow, ow, ow. And I just kept thinking about winning. So I think it's taught me a lot of positive mindset. Think big, think big all the time. Do big. And I mean, going back to the revenue question, we're thinking big Noah's father sold Timberland to the VF Corp for 2.3 billion, so what do we want to know? So it's like I think top down at Aram, everyone's thinking big, how can we build this up? And if you were to have somebody maybe on the team that wasn't in that ethos, right, I think it it'd be quite difficult. So I don't know, always even when I look at hiring, I kind of look at what sports did you do? I mean, it really, really gives you a perspective. I mean, one girl on our team was at a ski academy school, so it was skiing in school all the time at this elite level. And I think it teaches you the skills that you probably didn't get in school. It teaches you all this goal setting, being on time, training for something or time management.", "token_estimate": 1220, "speakers": ["Cole Heilborn", "Jax Mustafa"], "start_timestamp": "44:09", "end_timestamp": "44:25", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "e1f82b82-1f0d-4ea2-9daf-bb1da20c1bcb", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 17, "content": "Cole Heilborn (50:03): Yeah. Wow. Well, I feel like I have to ask the follow-up question. You obviously you're not afraid to just dive in and grind it out. With all of that though, able to find ways to take care of yourself and reenergize and come back to the desk fully charged,\n\nJax Mustafa (50:24): I would say I am a work in progress. So I retired from running back in September and I had to take an adequate amount of time off. And then I finally got to this place of I want to be normal human you exercising or meditating or whatever those initiatives are. And I definitely, I think even with Arum, I take this endurance mindset and I kind of put my all into it. And so I'm trying to rebalance out work-life balance, let's call it, right? And so I think one of the initial things they started doing, I'm like, I'm going to do 5K every day. And after 10 days I was like, oh my god, I have a 15 hour workday. No way. So it's like I'm realizing what is that balance? But I think it's so important to rebooting your soul and you're going to do better work if you take the 30 minute walk or you just go sit on our deck in the sun and alm out for a second, or you call your friend or, so I think it's getting at it and it's so important I think to me and my core and also to my team that on our weekly statuses we actually have a work-life balance part of your update. (51:52): It's kind like, Hey, I'm doing all this different stuff, update, and then it's, I got to asking over closing weekend. I want that to always be in such a fast paced, super aggressive environment. How do you check out for a second because you're just going to do better work. So trying to be the example that others will go forward for. So working on it.\n\nCole Heilborn (52:20): Good. Well, I'm glad you're able to find time to recharge. Jax, is there anything that we haven't talked about in our time today that you want to touch on, leave our audience with? I feel like we've kind of gotten a nice snapshot of the challenges of being a really small scrappy business, trying to run a really fast pace and hear a little bit about the specifics that you deal with. Is there anything though that we haven't covered?", "token_estimate": 548, "speakers": ["Cole Heilborn", "Jax Mustafa"], "start_timestamp": "50:03", "end_timestamp": "52:20", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "a881c2a5-9c29-4581-af6d-e4d7c8d96210", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 18, "content": "Jax Mustafa (52:48): I think overall for the audience, going back to your comment of a lot of people, maybe they're starting their own business or they're taking new initiatives with their careers, is to have that positive mindset, but just it's scary. It's really scary. I still wake up scared half the time. I want to do such a good job and I want Arum to be so successful. And I think it's just this balance of creating your toolkit with yourself of how do I manage that high-paced environment and my fears maybe of my insecurities, and how do I create a system around me that helps external, that helps me kind of level back up and stay positive and confident. My husband, he owns the software company and has been in a lot of similar positions to me. And so he becomes a great exterior sounding voice for me. My parents do. (53:53): So it's just like we have some advisors on our team that it's my favorite meeting every other week with one of our advisors. And so it's just like you feel this support system. And so I think with small business, especially remote, we're all remote. You feel alone. And so I would say if listeners out there are feeling like alone or I don't know if I can do it, you can do it. Just literally call somebody, be like, you know what? My best friend's bomb literally crushed X, Y, Z sewing business. I'm going to call them and I think that'll give me this new fresh, or those friends that pick you up. And I think that helps a lot when, because then adversity will be there more than big business, in my opinion. So I think that would be my biggest set of advice for everybody.\n\nCole Heilborn (54:49): Yeah, that's great. It makes sense. Find people, find people who can help you, find people who can lift you up, give you a different perspective.", "token_estimate": 446, "speakers": ["Jax Mustafa", "Cole Heilborn"], "start_timestamp": "52:48", "end_timestamp": "54:49", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "40f1060e-e0e1-44c3-b212-dc97068252af", "episode_id": "2c850aff-e12f-42e2-bb6b-e3d1dde0c502", "cms_item_id": "68225dfc7bb476527f8c488f", "chunk_index": 19, "content": "Jax Mustafa (54:59): Well, and in our environment there's a lot of pressure to almost figure it out on your own. It's so weird because we're in a social space right now that's really cluttered, but a lot of that clutter is just maybe unnecessary or not totally true. So it's made a lot of people just sit behind the screen and just almost live in the clutter where it's like my biggest thing that I've noticed lately is I'm just picking up the phone more, which is totally traditional untraditional, I guess. It's almost like step away from your screen and call that mentor you had seven years ago and totally external to your day-to-day business. And they may make you think of something totally different. And so I've got my toolbox of mentors over there and I'm going to get a lot more out of them than social media. So it's find those key people and don't let 'em go.\n\nCole Heilborn (56:03): Yeah, I love that. Well, Jax, I appreciate you taking the time to chat today. If folks want to follow along with you or with Aram, is there a good place they can go to connect?\n\nJax Mustafa (56:13): Yeah, Jax, Arum Life is my email and they can always just hit me up on Instagram too, which I think is J.\n\nCole Heilborn (56:23): Okay.\n\nJax Mustafa (56:24): Awesome. Always hear help.\n\nCole Heilborn (56:27): Awesome, Jax. Well I appreciate you taking the time and hopefully you were able to cross one of the things off of your to-do list today, but it was great getting to learn a little bit more about what you guys have going on, but behind the scenes. And it sounds like we should be on the lookout for some exciting new product releases coming out in the next year or so. Is that right?\n\nJax Mustafa (56:48): Yes. We have six products dropping in the fall and one I can go ahead and announce, we're going to launch a sandal Kickstarter, which should be an August 2nd. And so stay tuned for that. It's a really, really hard performance sandal that I think is going to be a very, very big competitor with some in the industry and it's also circular, so\n\nCole Heilborn (57:16): Very cool. Awesome. Well, Jack, have a great rest of your day and we'll chat soon.\n\nJax Mustafa (57:21): Thank you.\n\nCole Heilborn (57:22): Alright, see you. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 611, "speakers": ["Jax Mustafa", "Cole Heilborn"], "start_timestamp": "54:59", "end_timestamp": "57:22", "podcast_index": 103, "episode_name": "Ep 103: How to Run a Startup Marketing Plan | Jax Mustafa | Erem", "slug": "ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "web_url": "https://www.portsidepro.com/podcast-feed/ep-103-how-to-run-a-startup-marketing-plan-jax-mustafa-erem", "guest_name": "Jax Mustafa", "guest_title": "VP of Marketing at Erem", "categories": [], "short_description": "In this episode, Jax comes to us as the VP of Marketing at Erem, a footwear company inspired by the desert and committed to sustainability.", "podcast_length": "57:44"}, {"id": "0df21014-a5ff-4729-8e35-45f56c770232", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 0, "content": "Moez Faruqi (00:02): I think one of the things that excited me when I was joining White Duck was the vision and where they were trying to get to. If founders, they told me that we are just trying to be an online retailer. We just want to be on Amazon and make money and spend money on ads. That wouldn't have been as exciting for me. But when I hear things like we want to build a brand, we want to invest in sustainability, we want to build in education for our consumers, we want to build relationships with retailers and wholesalers and the Reis and Bash pros of the world, that starts to get a lot more exciting and get me interested.\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing podcast. My name is Cole Holborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Port Side Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Holborn, and today I'm sitting down with Mo Faruki. He's the head of marketing over at White Duck Outdoors Moose. How are you doing?\n\nMoez Faruqi (01:15): I'm doing great. Thanks for finally having me on. I know it's been a while that we've been trying to schedule this, but we finally we're sitting here and we're going to get done, so I'm excited\n\nCole Heilborn (01:23): We made it happen. I know it's been a bit of a whirlwind with the calendars lately, but we're sitting here on a nice Monday, looking forward to having this conversation, so I appreciate you taking the time.\n\nMoez Faruqi (01:35): Yep, same here. I'm excited for it.\n\nCole Heilborn (01:37): Well, moose, I'd love if you could give us a quick introduction to yourself, where you're located, where you're calling in from, and a little bit about your role with White Duck Outdoors.", "token_estimate": 536, "speakers": ["Moez Faruqi", "Cole Heilborn"], "start_timestamp": "00:02", "end_timestamp": "01:37", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "1a1878a6-cd21-44e5-887a-f01b9d32dc2f", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 1, "content": "Moez Faruqi (01:48): Yeah, for sure. So I'm Moose. I'm calling in from Pakistan actually. So ever since all the Lockdowns and COVID and pandemic started, I've been spending a lot more time with family and now I've kind of created a situation where when I have some free time, I fly back over here, spend time with family, and then whenever I'm required to be stateside for trade shows or meetings and so on, that's when I'm in the States. So yeah, that's where I'm calling in from. I am the head of marketing at White Duck, which means I cover pretty much everything that has to do with marketing from the website, conversion rates to email marketing, to video content, to influencers and ambassadors and what have you. We are effectively a one and a half person marketing team. I say half because there's a contractor, Samantha, she's awesome that we work with for social media and community engagement. (02:34): But other than that, for the last couple of years it's been mostly myself and we have one person who helps out in marketing ops. White Duck is an outdoor lifestyle brand, which means we build mostly, we manufacture all of our own gear and we retail direct to consumer. And I say outdoor lifestyle because it's not the intense hardcore hiking or backpacking gear that you might find from say a North Face or someone like that. It is more about just getting outdoors and reconnecting, and that's kind of what leads to our hashtag Reconnect now as well, which is we just want to encourage people to get outside, relax and enjoy themselves and reconnect with themselves or friends or family or nature. And so our bread and butter right now is tense and we have a complete range of canvas density build, but we also have a complete range of gear, which includes bags, dog beds, lock carriers, tarps, and so on. (03:23): And we are slowly and steadily moving our way towards becoming a full one-stop shop for everything for the outdoors and down the road, hopefully we're looking at other outdoor products as well. And yeah, I'd say our main focuses for why we exist as a brand is we want to build products that are durable and built to last, and they don't let you down. So if you're out and it's raining hard and you're in your tent, it's never going to blow away or collapse on you. We have a major focus on sustainability. So for example, all of our tents are made from VCI cotton, we recycle any waste products, and we're also part of the Climate Action core, just trying to reduce our emissions and impact on the planet. And we have a big focus on product design just to make sure that everything that we build is easy to use and for one of any experience level. So that's who we are.", "token_estimate": 675, "speakers": ["Moez Faruqi"], "start_timestamp": "01:48", "end_timestamp": "01:48", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "4810f0cc-5ebf-4d8d-9695-75d6c2d2b8d4", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 2, "content": "Cole Heilborn (04:11): Awesome. And if folks have not seen what you produce, just make some really incredible, really beautiful canvas tents. It's been a long standing goal of mine to have some sort of an excursion where I get to sleep in a canvas tent with a wood fire stove, and that's what you guys produce all shapes and sizes and they look pretty amazing. So yeah, one of these days it looks like a lot of fun.\n\nMoez Faruqi (04:38): Yeah, it's an awesome experience. Recently I've only camped in white duck tents and I think there's no going back for me to backpacking or synthetic tents. They're just so spacious, and I know this is a shameless plug, but they're just so spacious and so comfortable. I haven't gotten yet to the point where I've installed a wood stove inside. I personally am still a little iffy about that, but no, I love camping in the white duck tents. Yeah, it's great. And you should definitely get out in one as well.\n\nCole Heilborn (05:04): Yeah. Well, I'm excited to have you on the show. I feel like we've kind of caught white duck in the middle of this transition, and we're going to dive into what this transition is on today's episode. As you were describing when we connected previously, white Duck is in this state of flux where you guys are kind of changing where you were and you're working towards some pretty cool goals and some pretty exciting milestones. And I'll let you kind of explain the history and where you've come from. But today's topic is going to be all about the transformation from being an online retailer to becoming a fully established brand. And I think there's probably a lot of folks who can identify with the position that White Duck has been in, where you exist solely on e-commerce sites, you exist on your website and you sell product, you sell a great product, but beyond that, there's not much connection with your customers or your audience. This is kind of the spot that you have found yourselves in. I'd love if you could give us a little bit of history of the brand of the company, how you got started and why you're working towards this goal of becoming a fully developed brand.", "token_estimate": 538, "speakers": ["Cole Heilborn", "Moez Faruqi"], "start_timestamp": "04:11", "end_timestamp": "05:04", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "565bf967-cf4a-408c-89f9-db64f27d4562", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 3, "content": "Moez Faruqi (06:19): Definitely. So I can start off with the history. So we've been around for, I want to say about five years now. I've been on the team for two years, and we started almost exclusively, as you mentioned, an online retailer, which means we had a website and we were selling on say, Amazon and eBay. So the goal of the business initially was just manufacturing product, listing it online and making money. And so our main marketing spend or marketing strategy was direct response marketing, which means for anyone who does know, it means spending on marketing that will essentially results in a direct response from consumers by way of a purchase. So that could be paid ads or it could be display ads on Google for example. I was brought onto the team specifically to focus more on the brand side of things. So how do we expand beyond just being someone who's present on online marketplaces to being a full fleshed out brand where we develop direct connections with our employees, with our partners, with consumers, with brands or other retailers that we work with. (07:24): And so that's what I've been working on recently. I think where the distinction might lie or where that inspiration might come from is what you're trying to achieve as a business when you're first starting out. If I'm someone who say has connections with a manufacturer and I'm just trying to make some money, I may go produce a product as the cheapest possible cost in wherever my manufacturer is located, get that exported to the us, list it online in some marketplaces like Amazon, eBay, and so on, and just try and turn a profit and make money as quickly as I can. Where the difference might lie with a team like ours is we were trying to look beyond that, and while we started out as an online retailer, you could say once we were able to invest more into the business, it becomes more about having a positive impact on the community, for example. So all of us as people who are passionate about the outdoors, just listing something online and making money off of that isn't enough. And we could do that through any other industry or any other kinds of products, but if we're specifically in the outdoor space, which all of us love and we love getting outdoors, how can we provide more to the people who work at the company or our customers or partners or retailers and so on with a better experience overall and a better connection with who we are as a brand.", "token_estimate": 614, "speakers": ["Moez Faruqi"], "start_timestamp": "06:19", "end_timestamp": "06:19", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "02813564-57e7-4735-ac68-f216a077f098", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 4, "content": "Cole Heilborn (08:45): I was doing a quick Amazon search before we started recording today, and I typed in, I think canvas tents and White Duck was the first five 10 listings on Amazon, which is incredible because those are the most sought after positions for any sort of keyword on Amazon. So you've obviously done something right ranking well on e-commerce, and it's probably why you've had this initial success over the last five years. I'm curious if you could speak to that quickly, is what's the secret sauce there? Yeah, how do you guys manage that?", "token_estimate": 139, "speakers": ["Cole Heilborn"], "start_timestamp": "08:45", "end_timestamp": "08:45", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "5087d731-c03e-4317-9d73-bb1fb391ea3c", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 5, "content": "Moez Faruqi (09:20): Yeah, Amazon is important because it's just so convenient for consumers. So a lot of the times people won't even search Google for the brand's name. They will just go to Amazon and that will be their first try because almost everyone has a prime account. They want whatever they want to buy that same day. And so if someone's looking for say, gear or a tent, they might go to Amazon first and search canvas tents, or they might search duffel bags or tarps. So it is important to be present on those different platforms just to have that awareness and be in front of consumer's eyes. And so if someone's doing their research and they go to Amazon and search for White Duck and we have three star or two star tents or other gear, that doesn't reflect well on us as a brand. And so while I think most people know you don't make any money on Amazon, it's still important for us to have a great storefront, to have a great customer experience, to be rated extremely highly so that people know that what we make is something that they can rely on. (10:19): Then for us, it's a marketing challenge to get them to purchase directly from our website versus on Amazon, but it's still extremely important to be performing well on Amazon. So if we get a negative review or someone didn't have the best experience, we do everything we can to make that right, just because that in the end does reflect on who we are as a company. So we move a lot of gear on Amazon, tarps, bags, dog beds, all that kind of stuff. I think if you search for example, tarps as well, you'll see we have one of the highest rated tarps most reviewed, and again, that just helps get product out the door, helps move inventory and helps us fund all the marketing efforts that we're doing towards building a brand. But yeah, so if we're on it, we can't ignore it, but yeah, it doesn't make us money.\n\nCole Heilborn (11:09): You made the point to say that the goal is to use Amazon as kind of an awareness tool because most people go there to search for products or find new products, but then drive people to your website where they make the transaction. Why is that? Is that to circumnavigate the not making money part?", "token_estimate": 551, "speakers": ["Moez Faruqi", "Cole Heilborn"], "start_timestamp": "09:20", "end_timestamp": "11:09", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "69f9b530-32ef-4e6a-8517-06a398d0f2d3", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 6, "content": "Moez Faruqi (11:29): That's one aspect of it, but then it's also just about getting people into our community. And if we're speaking strictly from a marketing perspective, how do we maximize the lifetime value of the consumer? Because for example, on Amazon, there's no direct relationship with consumers, so we're not able to get in touch with them through email marketing. We're not able to get in touch with them about reviews through SMS marketing or make them aware of different products that we're offering, new product launches that we have trade shares we're going to be present at. And so it's about building that relationship with the consumer and that inevitably sure impacts our bottom line, but I think it's more about building that community and having those direct relationships with our customers.\n\nCole Heilborn (12:11): So you've set this goal of becoming this brand where you can connect with your audience, with your consumers, and you can share the initiatives and the values that White Duck cares about. How do you know when you've reached that goal? You've kind of painted this picture and along the journey that you're on today, where are you and how do you know when you have reached this point where you want to be?", "token_estimate": 311, "speakers": ["Moez Faruqi", "Cole Heilborn"], "start_timestamp": "11:29", "end_timestamp": "12:11", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "d1afb266-e7bc-48d4-868d-9fb0e29af690", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 7, "content": "Moez Faruqi (12:34): I think it's going to be ever evolving. The challenge, you never really reach that final stage, and I think it's just because the outdoor market and the world of marketing is constantly changing. So I'd say we've come pretty far in the last couple of years from where we were. For example, we were just a brand that had a website and it was listed on some online platforms. Now, for example, we work with a PR agency. We have tons of video content that we put out. We produce vlogs on YouTube, we have a pretty great Instagram account and we have an ambassador program. We work with influencers. We have a full fledged email and SMS marketing strategy. So we have our hands in all the right buckets of ensuring that we're doing what we can to build this community out and build a brand. We're providing education to our consumers. (13:27): So for example, if someone buys a product, they will automatically receive a post-purchase email workflow with all the details about their product, set up videos, how to maintenance, all that kind of stuff. Then we also on our blog produce long form content around how to take care of your tent. It could be how to pack for a winter camping trip. It could be how do you start a glamping business? And so we're making sure that we are providing our customers with the education they need, not just about using our products, but how to make the most of their time outdoors. And then as someone who's active in the outdoor community, we also have responsibility say to make sure that whoever is getting out with white duck products isn't negatively impacting their campsite or the planet, for example. So then we also need to provide resources on leave no trace or leave nothing but footprints or how to make sure that we're reducing our impact as much as possible as someone who's active in the space. (14:20): So that's kind of where we are as a brand, I'd say. But again, as is a constant challenge with marketing that's always changing. So just recently for example, this year we had a conversation internally about how do we take our marketing to the next level where engagement on Instagram for example, is dying. I think most people are aware of that or organic follower growth for us is extremely slow. Let's just say if we're not running a giveaway, for example, and so then the question becomes, okay, we are all millennials, but none of us are particularly well-versed in TikTok, but we know that that platform is blowing up, so what do we need to do as a brand now? What steps can we take to make sure that we're on this trend before it becomes too late if we've already missed the Instagram one, for example? And so that's just a very basic example of why this pursuit is never going to end because there will always be the next Instagram or TikTok or new marketing channel or new kind of engagement with your community that pops up, and we're going to have to find a way to accommodate that into our marketing and brand strategy.", "token_estimate": 751, "speakers": ["Moez Faruqi"], "start_timestamp": "12:34", "end_timestamp": "12:34", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "d1d2ca0a-d935-4724-8f11-303d8c22945e", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 8, "content": "Cole Heilborn (15:29): Sure, yeah, that's a great example. How would you define the health of a brand? Just speaking about brands as a whole and what makes a brand strong or what makes one healthy? We've talked about the relationship with the consumer. Would you say that the health of a brand is equal to the relationship that a brand has with its consumer or the strength of the relationship with its consumer\n\nMoez Faruqi (15:54): Health can probably be measured in two main ways. One is qualitative where you have the interactions you have with your consumer. So what are you hearing on a day-to-day basis from them? But then maybe that qualitative aspect of health of a brand goes beyond just the consumer and expands to the greater community. So when we have conversations, for example at PR or media shows with journalists and they come to our booth and see what products we have and the kind of feedback we get from them, if they hear about our sustainability initiatives or they hear about what our products are made from or they actually go inside the tents and experience them for themselves, what feedback are we getting from them? Are we going along the right lines or are we totally missing the mark? And I think it's also the kind of positive feedback that you get from everyone that you speak with. (16:37): So when we're first, for example, looking for a PR agency, do people sound excited to be starting to work with us when they hear about what we're trying to achieve? Or are people like, nah, I'm not so into White Duck. I'm not totally understanding the message, I'm not vibing with this brand. We don't want to bring these guys on as a client. So when it comes to say, retailers, if we're having conversations with wholesalers about Reselling White Duck, whether it's having conversations with journalists or the media, whether it's direct consumers, are we getting the right kind of positive feedback that makes us think we're moving in the right direction? And then again, if we aren't about certain products, so we launch a new camping chair and we don't get the right kind of feedback about that, are we nimble and agile enough to be able to change that and then respond to the feedback we're getting and increase our health if it was falling for any certain product in certain area? And then the quantitative aspect is of course in the numbers and the dollars. So are we healthy as a business? Are we not losing money? Are we spending in the right places? Are we seeing the right kinds of return on ad spend or is our average cost of say low enough to ensure that we're healthy and we're running and we're able to keep functioning as a brand and we're not syncing ourselves basically?", "token_estimate": 678, "speakers": ["Cole Heilborn", "Moez Faruqi"], "start_timestamp": "15:29", "end_timestamp": "15:54", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "f6bc2844-6bbd-4689-b309-c45f2c1edba6", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 9, "content": "Cole Heilborn (17:46): So yeah, that's a really interesting way to break it down. And I guess if you were being candid, where is White Duck along that journey? Where in that process are you?\n\nMoez Faruqi (17:56): I like to think we do a pretty good job, and that's not to toot my own horn, but I think like I mentioned before, we place a very strong emphasis on the customer experience. And so if we see that a certain product isn't performing the way we'd like or customers aren't getting their products fast enough, our shipping is broken or something else in the entire sales funnel isn't working the way we want, we do everything we can to fix that. And I'd say we're a pretty good team that operates that way, and I'm pretty proud about how far we've come in that sense. And just to give you a direct example, we launched Dog Beds last year and the zipper wasn't of the best quality, and we started to see that feedback from our customers and immediately we revises zippers and relaunched the product just to make sure that people are getting exactly what they expect when they purchase a white duck product. And that's always top of mind for us. And that never goes away weekly. We're having meetings about how are we improving the customer experience, how are we responding to what any kind of negative reviews or feedback we're getting and staying on top of that. So I feel like we're doing a good job and I think we're moving in the right direction for sure.\n\nCole Heilborn (19:06): Yeah, that's awesome. What are the biggest challenges that you face currently that are getting in the way preventing White Duck from getting where you guys want to go?", "token_estimate": 415, "speakers": ["Cole Heilborn", "Moez Faruqi"], "start_timestamp": "17:46", "end_timestamp": "19:06", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "5c7eb888-c369-426a-8aa6-829ac0b3e28e", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 10, "content": "Moez Faruqi (19:16): I'd say one of the main ones is bandwidth. As I mentioned at the start of the podcast, we are a one and a half person marketing team team. And so the biggest challenge for us is how do we get as much done in as little time as possible? So just the way we're structured at this time, we are a fairly lean team, so it just isn't inherently possible to be full throttle in every department that we want to be, which unfortunately means it isn't possible to be going a hundred percent on influencers and trade shows and PR and everything else that there is under the marketing umbrella. But that's just the reality we live in. And it isn't so much of a problem right now, but it may start to become one as we continue to scale. And I think it's also, that's kind of the internal one in terms of a SWOT analysis, what would we call that, the weakness at this time? And then if we talk about threats looking outwards, I think it's again, things we can't control but that keep popping up like new marketing platforms or a new competition or people who have more money to spend. And it's always about how are we doing everything we can in the context of the environments that we're working in to make sure that we're not falling behind. And I think, again, that TikTok example is a perfect example of that.\n\nCole Heilborn (20:33): Yeah, I mean it's easy to make a list of things and initiatives, projects that you want to start, but if you have no budget restrictions, you can do anything. But in a reality where everyone has to deal with a, how do you decide where to allocate that budget to try to move the needle as far as you can with any given dollar?", "token_estimate": 418, "speakers": ["Moez Faruqi", "Cole Heilborn"], "start_timestamp": "19:16", "end_timestamp": "20:33", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "c779c904-65a0-4e7a-be61-7e4accd1bbcd", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 11, "content": "Moez Faruqi (20:55): Yeah, a lot of that is based on just straight testing on digital platforms. That's a lot easier because you have direct numbers to work with tools that Google Analytics give you that information at your fingertips. And so for example, if we're working on Facebook ads, we can test out different creatives, we can test out different copies, we can do photos versus videos versus collages versus discounts and no discounts. And within a matter of a few weeks, you'll have the data to tell you which way you should be going. And we have certain roas or return on ad spend targets that we aim for. We try to keep our average cost of sale below a certain percentage, and as long as what we're spending money on is falling within the KPIs that we've set, then we know that we want to keep pushing in that direction. (21:40): And that isn't to say we aren't willing to spend money in new areas of marketing, which I think you have to do. For example, I'd say we're still fairly young in the influencer marketing space. We're still figuring it out. It's a little difficult for us because our tents, for example, are of a higher value. The average value of our tents is like a thousand dollars. So it's not something like apparel that we can send out in hundreds or thousands to different influencers or creators that we want to work with. So we do have to be a bit more intentional about how we approach working with creators. And so that's just an example of a space where we haven't quite figured it out. We're spending money on say, Instagram versus YouTube versus TikTok and just trying to get a sense of where we are getting that return on investment. And it could be in the form of reach or impressions, it could be in the form of direct sales, it could be in the form of affiliate sales, and it's just a matter of what targets we set and how much money we spend and what kind of return we're seeing. So it is testing within platforms, but then also testing across platforms and then seeing where we're hitting our targets and just kind of going gung-ho in those areas.", "token_estimate": 522, "speakers": ["Moez Faruqi"], "start_timestamp": "20:55", "end_timestamp": "20:55", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "d2a7dc51-1020-4182-9566-da41478a526f", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 12, "content": "Cole Heilborn (22:52): Yeah. I'm curious if you could share specifics and give us two examples. One scenario where you've set the target, you set the KPI, and then the results have far exceeded that. And maybe one example where you've set the goal and then you've fallen short and you're trying to figure out what isn't working.\n\nMoez Faruqi (23:08): Are we talking in any aspect of marketing,\n\nCole Heilborn (23:11): Any of the initiatives or programs that you're running?\n\nMoez Faruqi (23:15): Yeah, for sure. So one area that we saw a ton of success or have seen historically even across a few different campaigns is working with creators on YouTube. I think especially the kind of space that we're in, because it is a fairly decent investment for people. It's a long-term buy something that people hope to hold onto for many years. There's a lot of research that goes into understanding who has the best canvas stand, what White Duck is all about. And so a lot of times people are searching YouTube for white duck and stent or the best belt tent and so on. And so we've done a couple of campaigns with YouTubers. There was one who had over a million subscribers. We sent out a Wal tent and just that day we saw five or six x extra return on that product that we sent out, which was insane. And then there was a different YouTuber that we worked with. We sent them a log carrier and they had a 32nd mention in the middle of their video and we had a 10 x return on that spend. And that is the exact kind of thing that starts to tell us, okay, maybe YouTube's the kind of place we want to be focusing on. (24:24): I'd say just kind of sticking in the same vein, Instagram is still something we're trying to figure out. It also is just a matter of the nature of the beast and how it's different from YouTube. I think YouTube directs a lot more relevant traffic directly to our website, which is why it often results in sales Instagram. From my experience, I like to think of it more as billboard advertising, where you put content out there, people see it enough over time, and eventually they will be convinced to make that purchase when the time is right. But people aren't always ready to convert at that point. And so we have spent money on Instagram, but we don't always see that return on investment directly. But again, it just might be because we have to kind of judge it differently from the way we do YouTube.", "token_estimate": 605, "speakers": ["Cole Heilborn", "Moez Faruqi"], "start_timestamp": "22:52", "end_timestamp": "23:15", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "e6e0a573-9a77-45be-b9b9-e6c9b90e0466", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 13, "content": "Cole Heilborn (25:10): So all this seems like a lot of work, and you've kind of explained why you're on this journey. I'm curious though, who is this journey right for? Because I don't think not every online retailer needs to be a brand or even wants to be a brand. If someone is an online retailer, how should they decide? How should they weigh the pros and cons of doing what you're trying to do?\n\nMoez Faruqi (25:37): I think not to get too philosophical, it comes down to why you got into the business in the first place. I think one of the things that excited me when I was joining White Duck was the vision and where they were trying to get to. If when I was first having a conversation with the founders, they told me that we are just trying to be an online retailer. We just want to be an Amazon and make money and spend money on ads. That wouldn't have been as exciting for me. But when I hear things like we want to build a brand, we want to invest in sustainability, we want to build in education for our consumers, we want to be present at trade shows, we want to build relationships with retailers and wholesalers and the Reis and Bash pros of the world, that starts to get a lot more exciting and get me interested. (26:19): So really I think that's the first aspect of it. And then obviously it requires investment. It's not something that you can just pick up, wake up and be like, okay, I want to invest in my brand but not have or not be willing to throw money behind it. And then also it is a waiting game. It does take time when you are, for example, working with a PR agency, when you're investing in influencers, when you're building out an ambassador program or throwing money at video content, it's not something you'll see the return on investment on the next day the way you might with paid ads. I can invest $5,000 in Facebook ads and I will start to see that return immediately when I am building out a YouTube channel. I may not see that return for a couple of years, but that's something you have to be okay with. So it depends on that situation and whether you're willing to endure that for a bit of time. And I think that's probably what it comes down to for me at least.", "token_estimate": 551, "speakers": ["Cole Heilborn", "Moez Faruqi"], "start_timestamp": "25:10", "end_timestamp": "25:37", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "7cf1dd04-055d-46e3-88d1-bf1f8ce6cd13", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 14, "content": "Cole Heilborn (27:11): How long, so you've been doing this for a couple of years. How long, I know there is no finish line, but if you had to set a finish line date to when you hope you will have kind of figured out some of these components, how much longer do you expect to have?\n\nMoez Faruqi (27:29): Don't get me wrong. We've figured out some stuff. It's not like we're totally working in a haphazard way. We know how much we need to be spending and how much money we need to be making and in what areas we have a good sense of what works for us and what doesn't. And so I think we have figured out a lot of the parts, but aspects are still unknown to us and it's such a difficult question to answer. I think for me personally, as long as there are new avenues for marketing coming up, as long as there are new competitors, new products that we're building out, that challenge never stops. And so short answer is, unless we stagnate as a brand, unless we lose that passion for some reason, I don't think that's ever going to end. I apologize if that's a non-answer.\n\nCole Heilborn (28:19): No, but it's all out. I kind of gave you a loaded question.\n\nMoez Faruqi (28:24): Yeah, fair enough.\n\nCole Heilborn (28:26): What are some of the aspects you mentioned there's a few other aspects you're trying to figure out, and we've kind of talked about Instagram as being one of those, or maybe TikTok. Are there things outside of social platforms or channels that you're still trying to sort out?", "token_estimate": 374, "speakers": ["Cole Heilborn", "Moez Faruqi"], "start_timestamp": "27:11", "end_timestamp": "28:26", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "3809953c-8ba8-4611-b4cc-caa915bfaf9d", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 15, "content": "Moez Faruqi (28:43): Well, the PR world is one we've gotten into recently. We just started working with the PR agency in January, so that's extremely new to us. And when we were first signing on with them, one of directors of the agency mentioned that PR ages like a fine wine. And so we're probably not going to see the results of that for some time. We already have started seeing some results, but that's one of the aspects that we're working on newly. I'd say trade shows is something that we just started doing last year. We exhibited at one show and we're going to six this year and hopefully even more next year. But again, that's still new to us. This year was the first time we went to a hunting show, so that was totally new. It's the first time we're going to Overland Expo, first time we're going to be exhibiting at or, and then next year we'll be even more shows. (29:28): Website conversion rate optimization never ends. When I open up our website, it is a beautiful website and our devs and marketing team have done an awesome job, but there's always work to be done on the optimization side through AB testing and different tools, and that's something that never ends as well. And then I think just also just everything to do with product branding. So are we packaging our products the right way? Do we have the right catalogs and instruction manuals? Are we making the right kinds of video content for our consumers? Are we providing the perfect post-purchase experience? I think that's also an evolving thing. And just in that aspect, for example, we haven't revised our instruction manuals for our tents for maybe a couple of years now. So that's something that's an undertaking for us this year specifically. And that's a huge area of focus for us is the branding of our products, how they look and how we present them to a consumer. So those are just three examples of what a big focus is for us this year. And that might just change completely next year or it might just carry on into next year. It remains to be seen.\n\nCole Heilborn (30:31): Yeah. Awesome. What keeps you going\n\nMoez Faruqi (30:36): At White Duck? Or\n\nCole Heilborn (30:37): Yeah, why have you stuck around?", "token_estimate": 550, "speakers": ["Moez Faruqi", "Cole Heilborn"], "start_timestamp": "28:43", "end_timestamp": "30:37", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "6b858a26-b89a-4deb-9ca2-a8ac2d6974ac", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 16, "content": "Moez Faruqi (30:41): It's tons of fun, honestly, even though we are a small team, it's a lot better than twiddling my thumbs when I wake up in the morning and have nothing to do at work. The day's always busy, there's always stuff to be done, and the outdoor community is just awesome. Everyone I've met so far, and whether it's customers or it's partners or it's people at trade shows and just everyone has been amazing to get to know, and it's such a welcoming community. I think we met on Basecamp, which is such a great resource on Facebook as well, for anyone who doesn't know, it's an awesome way to find talent. And we posted on there for our TikTok creators as well. Got an awesome response. And I think everything about working in the outdoor community is great. Being able to get outside camp with our products, do product testing, speak to people, go to trade shows, yeah, build this awesome brand that seems to be moving in the right direction thus far. It's awesome to be part of. And yeah, short answer is it's tons of fun.\n\nCole Heilborn (31:48): Awesome. Well that's good. I'm glad it's fun. It sounds like you've been on a pretty fun journey and there's more to go. Yeah. Is there anything else that we haven't talked about so far that you want to go over today?\n\nMoez Faruqi (32:01): I think we've covered most of it. Yeah. I think in short, just when it comes to brand building, if I had to summarize what we've spoken about, the main thing for us is Insulin Conference in our community. So they know they're buying from a trusted brand and they can feel good about their purchase. And I think if any marketers are listening to this, the benefit of building a brand is that it's one of the best kinds of top of funnel marketing. So when you invest in video content, when you invest in your website, in sustainability, in building the right kinds of partnerships, that inevitably helps potential or prospective consumers find your brand online or YouTube or wherever else, and over time, it leads to a bigger community for your brand and in turn a better bottom line.", "token_estimate": 522, "speakers": ["Moez Faruqi", "Cole Heilborn"], "start_timestamp": "30:41", "end_timestamp": "32:01", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "58297aa4-cb72-4b89-bbb9-f9e3c412e231", "episode_id": "d3e255db-a513-4bb4-b830-a9ac1d43003b", "cms_item_id": "68225dfc7bb476527f8c4890", "chunk_index": 17, "content": "Cole Heilborn (32:50): Awesome. If folks want to follow along with you personally or with White Duck on any of the channels, where can they go?\n\nMoez Faruqi (32:57): So I have a private Instagram, so I'm not going to advertise that, but you can find me on LinkedIn. It's just my name always. And we are on all socials. Instagram is at White Duck Avatar, same on TikTok. YouTube is White, duck Outdoors, and Facebook as well. So yeah, we're active everywhere. You can find us on wherever, whatever your favorite platform is.\n\nCole Heilborn (33:19): Okay. Cool. Well, I appreciate you taking the time. I've been looking forward to checking in six months or a year from now and hearing how the journey's going, but it sounds like it's off to a great start.\n\nMoez Faruqi (33:31): Yeah, for sure. Thanks for having me on. This has been a lot of fun. I appreciate it.\n\nCole Heilborn (33:34): Yeah, no worries. Take care.\n\nMoez Faruqi (33:36): You as well. Thanks, bill.\n\nCole Heilborn (33:39): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 300, "speakers": ["Cole Heilborn", "Moez Faruqi"], "start_timestamp": "32:50", "end_timestamp": "33:39", "podcast_index": 104, "episode_name": "Ep 104: Building a Brand Versus Building an Online Retailer | Moez Faruqi | White Duck Outdoors", "slug": "ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "web_url": "https://www.portsidepro.com/podcast-feed/ep-104-building-a-brand-versus-building-an-online-retailer-moez-faruqi-white-duck-outdoors", "guest_name": "Moez Faruqi", "guest_title": "Head of Marketing at White Duck Outdoors", "categories": [], "short_description": "Moez Faruqi is the Head of Marketing at White Duck Outdoors. His role covers all aspects of the marketing side, including SMS/emails, influencers, product marketing, visual content, and more.", "podcast_length": "33:58"}, {"id": "4780774b-95d0-43e3-8e4a-9207d08eaa8a", "episode_id": "e600d296-07ae-4743-8610-17f024eaa9a8", "cms_item_id": "68225dfc7bb476527f8c483b", "chunk_index": 0, "content": "Cole Heilborn (00:00): Welcome to Brand Story. My name is Cole Hilborn and I'm going to be your host Today. Brand story is all about the marketing professionals who are working in the industry today. The landscape is constantly changing and evolving, takes really great smart people to run a successful brand, and that's what this podcast is all about. It's all about the people behind the brands we interact with, the challenges they face, as well as their personal journey. So if you're interested in learning more about what it takes to run a top brand, I hope you'll love this podcast and find something educational about it. Enjoy today's episode. Welcome to Brand Story. My name is Cole Holborn. I'll be your host today. Today I'm sitting down with John Drake, the Chief Strategy Officer at Drake Cooper. John, how are you doing?\n\nJohn Drake (00:42): I'm well. Cool. How are you\n\nCole Heilborn (00:44): Doing? Great. Thank you for joining us. I got to say it is a special episode because this is episode number 10, which means we've broken into the double digits.\n\nJohn Drake (00:56): I like it. That's great.\n\nCole Heilborn (00:59): Well, you're joining us down from Seattle, is that right?\n\nJohn Drake (01:02): That's right, yep.\n\nCole Heilborn (01:03): Tell us a little bit about Drake Cooper, who are you guys and what do you do?\n\nJohn Drake (01:09): You can think of us as an advertising agency first and foremost, and then within that we really specialize in what's called the mid-market. Small business typically isn't a client of ours, and you get over into large enterprise and we're not usually there except in certain circumstances. So we're in the mid-market for companies to help grow their brands. And our motto, if you will, is we build brands for the ambitious. And so we seek clients who really believe in the power of creativity, who really believe that good branding, good advertising, smart media, can really improve their organizations. And we have two offices. We're based in Boise, Idaho, and then I'm out of our Seattle office.", "token_estimate": 515, "speakers": ["Cole Heilborn", "John Drake"], "start_timestamp": "00:00", "end_timestamp": "01:09", "podcast_index": 10, "episode_name": "Ep 10: John Drake | A Life in the Ad World | Drake Coope‪r‬", "slug": "ep-10-john-drake-a-life-in-the-ad-world-drake-cooper", "web_url": "https://www.portsidepro.com/podcast-feed/ep-10-john-drake-a-life-in-the-ad-world-drake-cooper", "guest_name": null, "guest_title": null, "categories": [], "short_description": "\"We have this little pool of money, who do we focus it on?\" \"...we have to really define the problem in order to help.\"", "podcast_length": "44:32"}, {"id": "084c4db0-0992-4b2e-966e-2fb1161c0a65", "episode_id": "e600d296-07ae-4743-8610-17f024eaa9a8", "cms_item_id": "68225dfc7bb476527f8c483b", "chunk_index": 1, "content": "Cole Heilborn (01:58): So as the strategy officer, kind of paint us a picture of what your day looks like, what do you oversee, what do you get to work on?\n\nJohn Drake (02:06): I've done this my whole career, Cole, and so I've been doing this 23 years. And so now as chief strategy officer, I sit in the middle between understanding our clients and what they need to achieve their business objectives and trying to take those things and help distill it down into ways that creative people can understand what needs to happen to the business and then apply really creative and innovative solutions to do, for lack of a better word, really cool things that help a business sell stuff or communicate something. And so I sit in the middle and it's a really cool, I love sitting there because on one side you've got commerce, and on another side you've got art. And it's about trying to get the best out of both and putting stuff out in the world that people actually like that they respond to and say, yeah, that's helpful to me, or that's interesting, or that was entertaining and I want to do something with that. So I sit there and I oversee, oversee is a weird word. I work directly with our account management team and our account planning team, which writes all the creative briefs and our media insights and analytics teams which evaluate if the work was effective or not and where we can be better.\n\nCole Heilborn (03:26): So that's interesting. You kind of got your foot in two different camps, the left side of the brain, I suppose, on the right side of the brain. How do you translate and help communicate between those two parties?", "token_estimate": 410, "speakers": ["Cole Heilborn", "John Drake"], "start_timestamp": "01:58", "end_timestamp": "03:26", "podcast_index": 10, "episode_name": "Ep 10: John Drake | A Life in the Ad World | Drake Coope‪r‬", "slug": "ep-10-john-drake-a-life-in-the-ad-world-drake-cooper", "web_url": "https://www.portsidepro.com/podcast-feed/ep-10-john-drake-a-life-in-the-ad-world-drake-cooper", "guest_name": null, "guest_title": null, "categories": [], "short_description": "\"We have this little pool of money, who do we focus it on?\" \"...we have to really define the problem in order to help.\"", "podcast_length": "44:32"}, {"id": "64331e53-b486-4621-92ba-748c86e7e1d2", "episode_id": "e600d296-07ae-4743-8610-17f024eaa9a8", "cms_item_id": "68225dfc7bb476527f8c483b", "chunk_index": 2, "content": "John Drake (03:38): It starts with finding the right people first. On the client side, you get clients who really believe in what you do. You don't have to sell them on doing good stuff. They want good stuff and they want to be shown ideas that make them think differently. So if you start with that people, that type of person on one side, and then you've got on the agency side, you've got people who really care about having an impact, they really want clients to succeed. And you take that initial mindset. And then my philosophy towards strategy, and by the way, it's strategy just with advertising, it's not strategy. Strategy goes a bunch of different ways, but in my line of strategy, always kind of think of things as a little bit. You have to be a one part focused where it's like, this is the thing, think about that. Try to get away all the other parts and say, okay, this is the area you really need to think of. But within that area it's a little bit, you want to have a little bit of a mentality that's like a garden that you're doing. It's like (04:51): This is the thing we're really focused on. We really need to move this metric. This is what we need to get people to do. But within that, there's several ways we can probably do that and think about these things. And it could be that this idea here if done really, really well will do the job, whereas this idea here, yeah, it's a little bit different of a shift, but if we do that really, really well, that can make a difference too. So it's really about what can the client team and what can the agency team execute on really, really well that hits that one key objective that we need, we need to move.\n\nCole Heilborn (05:28): Yeah. Do you have any examples of that that would help further explain what you're talking about?", "token_estimate": 449, "speakers": ["John Drake", "Cole Heilborn"], "start_timestamp": "03:38", "end_timestamp": "05:28", "podcast_index": 10, "episode_name": "Ep 10: John Drake | A Life in the Ad World | Drake Coope‪r‬", "slug": "ep-10-john-drake-a-life-in-the-ad-world-drake-cooper", "web_url": "https://www.portsidepro.com/podcast-feed/ep-10-john-drake-a-life-in-the-ad-world-drake-cooper", "guest_name": null, "guest_title": null, "categories": [], "short_description": "\"We have this little pool of money, who do we focus it on?\" \"...we have to really define the problem in order to help.\"", "podcast_length": "44:32"}, {"id": "90b76638-1c41-4c27-9ef9-2dbfe89300be", "episode_id": "e600d296-07ae-4743-8610-17f024eaa9a8", "cms_item_id": "68225dfc7bb476527f8c483b", "chunk_index": 3, "content": "John Drake (05:33): Well, sure, that's a good question. To start with, visit Idaho is an interesting one because when you're thinking about tourism, there's a lot of different things that can work and there's some basic principles of tourism that's really, really good to do. But with us, one of the things that we realized is that if we focus on families, one of the things we needed to do, the metric we needed to do is we needed to increase visitation. So a couple of ways to do that. One way is what if we just focused on families? So the brief that we wrote up was all about focusing on that and why that's a smart strategy for that brand. So everybody thought about that. And then when the creative hit the table and the creative idea was what was called 18 summers, the moment that hit the table, it was like, that's brilliant, that's great, let's do that. And so that happened and it's been very, very successful.\n\nCole Heilborn (06:42): And that leads into the next set of questions is talking about that campaign. Tell us a little bit more about you guys were going in to try to bring in more tourism, and you guys have worked with Visit Idaho for quite some time now, so you have this great relationship, but what were the results from that campaign and what'd you guys learn after working through that?", "token_estimate": 329, "speakers": ["John Drake", "Cole Heilborn"], "start_timestamp": "05:33", "end_timestamp": "06:42", "podcast_index": 10, "episode_name": "Ep 10: John Drake | A Life in the Ad World | Drake Coope‪r‬", "slug": "ep-10-john-drake-a-life-in-the-ad-world-drake-cooper", "web_url": "https://www.portsidepro.com/podcast-feed/ep-10-john-drake-a-life-in-the-ad-world-drake-cooper", "guest_name": null, "guest_title": null, "categories": [], "short_description": "\"We have this little pool of money, who do we focus it on?\" \"...we have to really define the problem in order to help.\"", "podcast_length": "44:32"}]
